import{d as l,c,a as e,t as d,g as t,o as y,_ as u}from"./index-BblzrX3Q.js";const k=[{lesson:1,title:"Excuse me!",titleCn:"对不起！",en:["Excuse me!","Yes?","Is this your handbag?","Pardon?","Is this your handbag?","Yes, it is.","Thank you very much."],zh:["对不起","什么事？","这是您的手提包吗？","对不起，请再说一遍。","这是您的手提包吗？","是的，是我的。","非常感谢！"],words:[{en:"excuse",cn:"v. 原谅"},{en:"me",cn:"pron.我(宾格)"},{en:"yes",cn:"adv. 是的"},{en:"is",cn:"v. be 动词现在时第三人称单数"},{en:"this",cn:"pron.这"},{en:"your",cn:"possessive adjective 你的，你们的"},{en:"handbag",cn:"n. （女用）手提包"},{en:"pardon",cn:"int. 原谅，请再说一遍"},{en:"it",cn:"pron.它"},{en:"thank you",cn:"感谢你（们）"},{en:"very much",cn:"非常地"}]},{lesson:3,title:"Sorry, sir.",titleCn:"对不起，先生。",en:["My coat and my umbrella please.","Here is my ticket.","Thank you, sir.","Number five.","Here's your umbrella and your coat.","This is not my umbrella.","Sorry sir.","Is this your umbrella?","No, it isn't.","Is this it?","Yes, it is.","Thank you very much."],zh:["请把我的大衣和伞拿给我。","这是我（寄存东西）的牌子。","谢谢，先生。","是5号。","这是您的伞和大衣","这不是我的伞。","对不起，先生。","这把伞是您的吗？","不，不是！","这把是吗？","是，是这把","非常感谢。"],words:[{en:"umbrella",cn:"n. 伞"},{en:"please",cn:"int. 请"},{en:"here",cn:"adv. 这里"},{en:"my",cn:"possessive adjective1 我的"},{en:"ticket",cn:"n. 票"},{en:"number",cn:"n. 号码"},{en:"five",cn:"num. 五"},{en:"sorry",cn:"adj. 对不起的"},{en:"sir",cn:"n. 先生"},{en:"cloakroom",cn:"n. 衣帽存放处"}]},{lesson:5,title:"Nice to meet you",titleCn:"很高兴见到你。",en:["MR. BLAKE: Good morning.","STUDENTS: Good morning, Mr. Blake.","MR. BLAKE: This is Miss Sophie Dupont.","Sophie is a new student.","She is French.","MR. BLAKE: Sophie, this is Hans.","He is German.","HANS: Nice to meet you.","MR. BLAKE: And this is Naoko.","She's Japanese.","NAOKO: Nice to meet you.","MR. BLAKE: And this is Chang-woo.","He's Korean.","CHANG-WOO: Nice to meet you.","MR. BLAKE: And this is Luming.","He is Chinese.","LUMNG: Nice to meet you.","MR. BLAKE: And this is Xiaohui.","She's Chinese, too.","XIAOHUI: Nice to meet you."],zh:["布莱克先生：早上好。","学      生：早上好，布莱克先生。","布莱克先生：这位是索菲娅.杜邦小姐。索菲娅是个新学生。她是法国人。","布莱克先生：索菲娅，这位是汉斯。他是德国人。","汉      斯：很高兴见到你。","布莱克先生：这位是直子。她是日本人。","直      子：很高兴见到你。","布莱克先生：这位是昌宇。他是韩国人。","昌      宇：很高兴见到你。","布莱克先生：这位是鲁明。他是中国人。","鲁      明：很高兴见到你。","布莱克先生：这位是晓惠。她也是中国人。","晓      惠：很高兴见到你。"],words:[{en:"Mr.",cn:"先生"},{en:"good",cn:"adj. 好"},{en:"Miss",cn:"小姐"},{en:"new",cn:"adj. 新的"},{en:"student",cn:"n.   学生"},{en:"French",cn:"adj. & n. 法国人"},{en:"German",cn:"adj. & n. 德国人"},{en:"nice",cn:"adj. 美好的"},{en:"meet",cn:"v.   遇见"},{en:"Japanese",cn:"adj. & n. 日本人"},{en:"Korean",cn:"adj. & n. 韩国人"},{en:"Chinese",cn:"adj. & n. 中国人"},{en:"too",cn:"adv. 也"}]},{lesson:7,title:"Are you a teacher?",titleCn:"你是教师吗？",en:["ROBERT: I am a new student.","My name's Robert.","SOPHIE: Nice to meet you.","My name's Sophie.","ROBERT: Are you French?","SOPHIE: Yes, I am.","SOPHIE: Are you French too?","ROBERT: No, I am not.","SOPHIE: What nationality are you?","ROBERT: I'm Italian.","ROBERT: Are you a teacher?","SOPHIE: No, I'm not.","ROBERT: What's your job?","SOPHIE: I'm a keyboard operator.","SOPHIE: What's your job?","ROBERT: I'm an engineer."],zh:["罗伯特：我是个新学生，我的名字叫罗伯特。","索菲娅：很高兴见到你。我的名字叫索菲娅。","罗伯特：你是法国人吗？","索菲娅：是的，我是法国人。","索菲娅：你也是法国人吗？","罗伯特：不，我不是。","索菲娅：你是哪国人？","罗伯特：我是意大利人。","罗伯特：你是教师吗？","索菲娅：不，我不是。","罗伯特：你是做什么工作的？","索菲娅：我是电脑录入员。","索菲娅：你是做什么工作的？","罗伯特：我是工程师。"],words:[{en:"I",cn:"pron.我"},{en:"am",cn:"v.   be 动词现在时第一人称单数"},{en:"are",cn:"v.   be 动词现在时复数"},{en:"name",cn:"n.   名字"},{en:"what",cn:"adj. & pron. 什么"},{en:"nationality",cn:"n.   国籍"},{en:"job",cn:"n.   工作"},{en:"keyboard",cn:"n.   电脑键盘"},{en:"operator",cn:"n.   操作人员"},{en:"engineer",cn:"n.   工程师"}]},{lesson:9,title:"How are you today?",titleCn:"今天好吗？",en:["STEVEN: Hello, Helen.","HELEN: Hi, Steven.","STEVEN: How are you today?","HELEN: I'm very well, thank you.","And you?","STEVEN: I'm fine, thanks.","STEVEN: How is Tony?","HELEN: He's fine, thanks.","How's Emma?","STEVEN: She's very well, too, Helen.","STEVEN: Goodbye, Helen.","Nice to see you.","HELEN: Nice to see you, too, Steven.","Goodbye."],zh:["史蒂文：你好，海伦","海  伦：你好，史蒂文","史蒂文：你今天好吗？","海  伦：很好，谢谢你。你好吗？","史蒂文：很好，谢谢。","史蒂文：托尼好吗？","海  伦：他很好，谢谢。埃玛好吗？","史蒂文：她也很好，海伦。","史蒂文：再见，海伦。见到你真高兴。","海  伦：我见到你也很高兴，史蒂文。再见。"],words:[{en:"hello",cn:"int. 喂（表示问候）"},{en:"hi",cn:"int. 喂，嗨"},{en:"today",cn:"adv. 今天"},{en:"well",cn:"adj. 身体好"},{en:"fine",cn:"adj. 美好的"},{en:"thanks",cn:"int. 谢谢"},{en:"goodbye",cn:"int. 再见"},{en:"see",cn:"v.   见"}]},{lesson:11,title:"Is this your shirt?",titleCn:"这是你的衬衫吗？",en:["TEACHER：Whose shirt is that?","TEACHER：Is this your shirt, Dave?","DAVE: No. Sir.","It's not my shirt.","DAVE: This is my shirt.","My shirt's blue.","TEACHER: Is this shirt Tim's?","DAVE: Perhaps it is, sir.","Tim's shirt's white.","TEACHER：Tim!","TIM: Yes, sir?","TEACHER：Is this your shirt?","TIM: Yes, sir.","TEACHER：Here you are.","Catch!","TIM: Thank you, sir."],zh:["老师：那是谁的衬衫？","老师：戴夫， 这是你的衬衫吗？","戴夫：不， 先生。这不是我的衬衫。","戴夫：这是我的衬衫。我的衬衫是蓝色的。","老师：这件衬衫是蒂姆的吗？","戴夫：也许是，先生。蒂姆的衬衫是白色的。","老师：蒂姆！","蒂姆: 什么事，先生。","老师：这是你的衬衫吗？","蒂姆：是的，先生。","老师：给你。接着！","蒂姆：谢谢您，先生。"],words:[{en:"whose",cn:"pron.谁的"},{en:"blue",cn:"adj. 蓝色的"},{en:"perhaps",cn:"adv. 大概"},{en:"white",cn:"adj. 白色的"},{en:"catch",cn:"v.   抓住"}]},{lesson:13,title:"A new dress",titleCn:"一件新连衣裙",en:["LOUISE: What colour's your new dress?","ANNA: It's green.","ANNA: Come upstairs and see it.","LOUISE: Thank you.","ANNA: Look!","Here it is!","LOUISE: That's a nice dress.","It's very smart.","ANNA: My hat's new, too.","LOUISE: What colour is it?","ANNA: It's the same colour.","It's green, too.","LOUISE: That is a lovely hat!"],zh:["路易丝：你的新连衣裙是什么颜色的？","安  娜：是绿色的。","安  娜：到楼上来看看吧。","路易丝：谢谢。","安  娜：瞧，就是这件。","路易丝：这件连衣裙真好，真漂亮。","安  娜：我的帽子也是新的。","路易丝：是什么颜色的？","安  娜：一样的颜色， 也是绿的。","路易丝：真是一顶可爱的帽子！"],words:[{en:"colour",cn:"n.   颜色"},{en:"green",cn:"adj. 绿色"},{en:"come",cn:"v.   来"},{en:"upstairs",cn:"adv. 楼上"},{en:"smart",cn:"adj. 时髦的，巧妙的"},{en:"hat",cn:"n.   帽子"},{en:"same",cn:"adj. 相同的"},{en:"lovely",cn:"adj. 可爱的，秀丽的"}]},{lesson:15,title:"Your passports, please.",titleCn:"请出示你们的护照。",en:["CUSTOMS OFFICER: Are you Swedish?","GIRLS: No, we are not.","We are Danish.","CUSTOMS OFFICER: Are your friends Danish, too?","GIRLS: No, they aren't.","They are Norwegian.","CUSTOMS OFFICER: Your passports, please.","GIRLS: Here they are.","CUSTOMS OFFICER: Are these your cases?","GIRLS: No, they aren't.","GIRLS: Our cases are brown.","Here they are.","CUSTOMS OFFICER: Are you tourists?","GIRLS: Yes, we are.","CUSTOMS OFFICER: Are your friends tourists too?","GIRLS: Yes, they are.","CUSTOMS OFFICER: That's fine.","GIRLS: Thank you very much."],zh:["海关官员：你们是瑞典人吗？","姑 娘 们：不，我们不是瑞典人。我们是丹麦人。","海关官员：你们的朋友也是丹麦人吗？","姑 娘 们：不，他们不是丹麦人。他们是挪威人。","海关官员：请出示们的护照。","姑 娘 们：给您。","海关官员：这些是你们的箱子吗？","姑 娘 们：不，不是。","姑 娘 们：我们的箱子是棕色的。在这儿呢。","海关官员：你们是来旅游的吗？","姑 娘 们：是的，我们是来旅游的。","海关官员：你们的朋友也是来旅游的吗？","姑 娘 们：是的，他们也是。","海关官员：好了。","姑 娘 们：非常感谢。"],words:[{en:"customs",cn:"n.   海关"},{en:"officer",cn:"n.   官员"},{en:"girl",cn:"n.   女孩，姑娘"},{en:"Danish",cn:"adj.& n. 丹麦人"},{en:"friend",cn:"n.   朋友"},{en:"Norwegian",cn:"adj. & n. 挪威人"},{en:"passport",cn:"n.   护照"},{en:"brown",cn:"adj. 棕色的"},{en:"tourist",cn:"n.   旅游者"}]},{lesson:17,title:"How do you do?",titleCn:"",en:["Come and meet our employees, Mr. Richards.","Thank you, Mr. Jackson.","This is Nicola Grey, and this is Claire Taylor.","How do you do?","Those women are very hard-working.","What are their jobs?","They’re keyboard operators.","This is Michael Baker, and this is Jeremy Short.","How do you do?","They aren’t very busy!","What are their jobs?","They’re sales reps.","They are very lazy.","Who is this young man?","This is Jim.","He is our office assistant."],zh:["杰克逊先生：来见见我们的雇员，","理查兹先生。","理查兹先生：谢谢，杰克逊先生。","杰克逊先生：这位是尼克拉.格雷，","这位是克莱尔.泰勒。","理查兹先生：你们好！","理查兹先生：那些姑娘很勤快。","她们是做什么工作的？","杰克逊先生：她们是电脑录入员。","杰克逊先生：这位是迈克尔.贝克，","这位是杰里米.肖特。","理查兹先生：你们好！","理查兹先生：他们不很忙吧！","他们是做什么工作的？","杰克逊先生：他们是推销员，他们非常懒。","理查兹先生：这个年轻人是谁？","杰克逊先生：他是吉姆，","是我们办公室的勤杂人员。"],words:[{en:"employee",cn:"n. 雇员"},{en:"hard-working",cn:"adj. 勤奋的"},{en:"sales reps",cn:"推销员"},{en:"man",cn:"n. 男人"},{en:"office",cn:"n. 办公室"},{en:"assistant",cn:"n. 助手"}]},{lesson:19,title:"Tired and thirsty",titleCn:"",en:["What’s the matter, children?","We are tired and thirsty, Mum.","Sit down here.","Are you all right now?","No, we aren’t.","Look!","There’s an ice cream man.","Two ice creams please.","Here you are, children.","Thanks, Mum.","These ice creams are nice.","Are you all right now?","Yes, we are, thank you."],zh:["母 亲： 怎么啦，孩子们？","女 孩： 我们累了……","男 孩： ……口也渴，妈妈。","母 亲： 坐在这儿吧。","母 亲： 你们现在好些了吗？","男 孩： 不， 还没有。","母 亲： 瞧！有个卖冰淇淋的。","母 亲： 请拿两份冰淇淋。","母 亲： 拿着，孩子们。","孩子们： 谢谢，妈妈。","女 孩： 这些冰淇淋真好吃。","母 亲： 你们现在好了吗？","孩子们： 是的，现在好了，谢谢您！"],words:[{en:"matter",cn:"n. 事情"},{en:"children",cn:"n. 孩子们（child的复数）"},{en:"tired",cn:"adj. 累,疲乏"},{en:"boy",cn:"n. 男孩"},{en:"thirsty",cn:"adj. 渴"},{en:"Mum",cn:"n. 妈妈（儿语）"},{en:"sit down",cn:"坐下"},{en:"right",cn:"adj. 好，可以"},{en:"ice cream",cn:"冰淇淋"}]},{lesson:21,title:"Which book?",titleCn:"",en:["Give me a book please, Jane.","Which book?","This one?","No, not that one. The red one.","This one?","Yes, please.","Here you are.","Thank you."],zh:["丈夫：请拿本书给我，简。","妻子：哪一本？","妻子：是这本吗？","丈夫：不，不是那本。是那本红皮的。","妻子：这本吗？","丈夫：是的，请给我。","妻子：给你。","丈夫：谢谢。"],words:[{en:"give",cn:"v. 给"},{en:"one",cn:"pron.一个"},{en:"which",cn:""},{en:"question word",cn:"哪一个"}]},{lesson:23,title:"Which glasses?",titleCn:"",en:["Give me some glasses please, Jane.","Which glasses?","These glasses?","No, not those. The ones on the shelf.","These?","Yes, please.","Here you are.","Thanks."],zh:["丈夫：请拿给我几只玻璃杯，简。","妻子：哪几只？","妻子：这几只吗？","丈夫：不，不是那几只。是架子上的那几只。","妻子：这几只？","丈夫：是的，请拿给我。","妻子：给你。","丈夫：谢谢。"],words:[{en:"on",cn:"prep.在……之上"},{en:"shelf",cn:"n. 架子，搁板"}]},{lesson:25,title:"Mrs. Smith’s kitchen",titleCn:"",en:["Mrs. Smith’s kitchen is small.","There is a refrigerator in the kitchen.","The refrigerator is white.","It is on the right.","There is an electric cooker in the kitchen.","The cooker is blue.","It is on the left.","There is a table in the middle of the room.","There is a bottle on the table.","The bottle is empty.","There is a cup on the table, too.","The cup is clean."],zh:["史密斯夫人的厨房很小。","厨房里有个电冰箱。","冰箱的颜色是白的。","它位于房间右侧。","厨房里有个电灶。","电灶的颜色是蓝的。","它位于房间左侧。","房间的中央有张桌子。","桌子上有个瓶子。","瓶子是空的。","桌子上还有一只杯子。","杯子很干净。"],words:[{en:"Mrs.",cn:"夫人"},{en:"kitchen",cn:"n. 厨房"},{en:"refrigerator",cn:"n. 电冰箱"},{en:"right",cn:"n. 右边"},{en:"electric",cn:"adj. 带电的，可通电的"},{en:"left",cn:"n. 左边"},{en:"cooker",cn:"n. 炉子，炊具"},{en:"middle",cn:"n. 中间"},{en:"of",cn:"prep.（属于）……的"},{en:"room",cn:"n. 房间"},{en:"cup",cn:"n. 杯子"}]},{lesson:27,title:"Mrs. Smith’s living room",titleCn:"",en:["Mrs. Smith’s living room is large.","There is a television in the room.","The television is near the window.","There are some magazines on the television.","There is a table in the room.","There are some newspapers on the table.","There are some armchairs in the room.","The armchairs are near the table.","There is a stereo in the room.","The stereo is near the door.","There are some books on the stereo.","There are some pictures in the room.","The pictures are on the wall."],zh:["史密斯夫人的客厅很大。","客厅里有台电视机。","电视机靠近窗子。","电视机上放着几本杂志。","客厅里有张桌子。","桌上放着几份报纸。","客厅里有几把扶手椅。","那些扶手椅靠近桌子。","客厅里有台立体声音响。","音响靠近门。","音响上面有几本书。","客厅里有几幅画。","画挂在墙上。"],words:[{en:"living room",cn:"客厅"},{en:"near",cn:"prep.靠近"},{en:"window",cn:"n. 窗户"},{en:"armchair",cn:"n. 扶手椅"},{en:"door",cn:"n. 门"},{en:"picture",cn:"n. 图画"},{en:"wall",cn:"n. 墙"}]},{lesson:29,title:"Come in, Amy.",titleCn:"",en:["Come in, Amy.","Shut the door, please.","This bedroom is very untidy.","What must I do, Mrs. Jones?","Open the window and air the room.","Then put these clothes in the wardrobe.（衣橱）","Then make the bed.","Dust the dressing table.","Then sweep the floor."],zh:["琼斯夫人：进来，艾米。","琼斯夫人：请把门关上。","琼斯夫人：这卧室太不整洁了。","艾 米：我应该做些什么呢，琼斯夫人？","琼斯夫人：打开窗子，给房间通通风。","琼斯夫人：然后把这些衣服放进衣橱里去。","琼斯夫人：再把床整理一下。","琼斯夫人：掸掉梳妆台上的灰尘。","琼斯夫人：然后扫扫地。"],words:[{en:"shut",cn:"v. 关门"},{en:"bedroom",cn:"n. 卧室"},{en:"untidy",cn:"adj. 乱，不整齐"},{en:"must",cn:"modal verb 必须，应该"},{en:"open",cn:"v. 打开"},{en:"air",cn:"v. 使 … 通风，换换空气"},{en:"put",cn:"v. 放置"},{en:"clothes",cn:"n. 衣服"},{en:"wardrobe",cn:"n. 大衣柜"},{en:"dust",cn:"v. 掸掉灰尘土"},{en:"sweep",cn:"v. 扫"}]},{lesson:31,title:"Where’s Sally?",titleCn:"",en:["Where’s Sally, Jack?","She’s in the garden, Jane.","What’s she doing?","She’s sitting under the tree.","Is Tim in the garden, too?","Yes, he is.","He’s climbing the tree.","I beg your pardon?","Who’s climbing the tree.","Tim is.","What about the dog?","The dog’s in the garden, too.","It’s running across the grass.","It’s running after a cat."],zh:["简：杰克，萨莉在哪儿？","杰克：她在花园里，简。","简：她在干什么？","杰克：她正在树荫下坐着。","简：蒂姆也在花园里吗？","杰克：是的，他也在花园里。他正在爬树。","简：你说什么？谁在爬树？","杰克：蒂姆在爬树。","简：那么狗呢？","杰克：狗也在花园里。它正在草地上跑，","在追一只猫。"],words:[{en:"garden",cn:"n. 花园"},{en:"under",cn:"prep.在……这下"},{en:"tree",cn:"n. 树"},{en:"climb",cn:"v. 爬，攀登"},{en:"who",cn:"pron.谁"},{en:"run",cn:"v. 跑"},{en:"grass",cn:"n. 草，草地"},{en:"after",cn:"prep.在……之后"},{en:"across",cn:"prep.横过，穿过"},{en:"cat",cn:"n. 猫"}]},{lesson:33,title:"A fine day",titleCn:"",en:["It’s a fine day today.","There are some clouds in the sky, but the sun is shining.","Mr Jones’s with his family.","They are walking over the bridge.","There are some boats on the river.","Mr Jones and his wife are looking at them.","Sally is looking at a big ship.","The ship is going under the bridge.","Tim is looking at an airplane.","The airplane is flying over the river."],zh:["今天天气好。","天空中飘着几朵云，但阳光灿烂。","琼斯先生同他的家人在一起。","他们正在过桥。","河上有几艘船。","琼斯先生和他的妻子正在看这些船。","莎莉正在观看一艘大船。","那船正从桥下驶过。","蒂姆正望着一架飞机。","飞机正从河上飞过。"],words:[{en:"day",cn:"n. 日子"},{en:"cloud",cn:"n. 云"},{en:"sky",cn:"n. 天空"},{en:"sun",cn:"n. 太阳"},{en:"shine",cn:"v. 照耀"},{en:"with",cn:"prep. 和……在一起"},{en:"family",cn:"n. 家庭（成员）"},{en:"walk",cn:"v. 走路, 步行"},{en:"over",cn:"prep.跨越，在……之上"},{en:"bridge",cn:"n. 桥"},{en:"boat",cn:"n. 船"},{en:"river",cn:"n. 河"},{en:"ship",cn:"n. 轮船"},{en:"airplane",cn:"n. 飞机"},{en:"fly",cn:"v. 飞"}]},{lesson:35,title:"Our village",titleCn:"",en:["This is a photograph of our village.","Our village is in a valley.","It is between two hills.","The village is on a river.","Here is another photograph of the village.","My wife and I are walking along the banks of the river.","We are on the left.","There is a boy in the water.","He is swimming across the river.","Here is another photograph.","This is the school building.","It is beside a park.","The park is on the right.","Some children are coming out of the building.","Some of them are going into the park."],zh:["这是我们村庄的一张照片。","我们的村庄坐落在一个山谷之中。","它们于两座小山之间。","它靠近一条小河。","这是我们村庄的另一张照片。","我和妻子沿河岸走着。","我们在河的左侧。","河里面有个男孩。","他正横渡小河。","这是另一张照片。","这是学校大楼。","它位于公园的旁边。","公园在右面。","一些孩子正从楼里出来。","他们中有几个正走进公园。"],words:[{en:"photograph",cn:"n. 照片"},{en:"village",cn:"n. 村庄"},{en:"valley",cn:"n. 山谷"},{en:"between",cn:"prep.在……之间"},{en:"hill",cn:"n. 小山"},{en:"another",cn:""},{en:"det.",cn:"另一个"},{en:"wife",cn:"n. 妻子"},{en:"along",cn:"prep.沿着"},{en:"bank",cn:"n. 河岸"},{en:"water",cn:"n. 水"},{en:"swim",cn:"v. 游泳"},{en:"building",cn:"n. 大楼，建筑物"},{en:"park",cn:"n. 公园"},{en:"into",cn:"prep.进入"}]},{lesson:37,title:"Making a bookcase",titleCn:"",en:["You’re working hard, George.","What are you doing?","I’m making a bookcase.","Give me that hammer please, Dan.","Which hammer.","This one?","No, not that one.","The big one.","Here you are.","Thanks, Dan.","What are you going to do now, George?","I’m going to paint it.","What colour are you going to paint it?","I’m going to paint it pink.","Pink!","This bookcase isn’t for me.","It’s for my daughter, Susan.","Pink’s her favorite colour."],zh:["丹 ：你干得真辛苦，乔治。你在干什么呢？","乔治：我正在做书架。","乔治：请把那把锤子拿给我。丹。","丹 ：哪一把？是这把吗？","乔治：不，不是那把。是那把大的。","丹 ：给你。","乔治：谢谢。丹。","丹 ：你现在打算干什么，乔治？","乔治：我打算把它漆一下。","丹 ：你打算把它漆成什么颜色？","乔治：我想漆成粉红色。","丹 ：粉红色！","乔治：这个书架不是为我做的，","是为我的女儿苏珊做的。","粉红色是她最喜欢的颜色。"],words:[{en:"work",cn:"v. 工作"},{en:"hard",cn:"adv. 努力地"},{en:"make",cn:"v. 做"},{en:"bookcase",cn:"n. 书橱，书架"},{en:"hammer",cn:"n. 锤子"},{en:"paint",cn:"v. 上漆，涂"},{en:"pink",cn:"n.& adj. 粉红色"},{en:"favourite",cn:"adj. 最喜欢的"}]},{lesson:39,title:"Don’t drop it!",titleCn:"",en:["What are you going to do with that vase, Penny?","I’m going to put it on this table, Sam.","Don’t do that.","Give it to me.","What are you going to do with it?","I’m going to put it here, in front of the window.","Be careful.","Don’t drop it!","Don’t put it there, Sam.","Put it here, on this shelf.","There we are!","It’s a lovely vase.","Those flowers are lovely, too."],zh:["萨姆：你打算如何处理那花瓶？","彭妮：我打算把它放在这张桌子上，萨姆。","萨姆：不要放在那儿，把它给我。","彭妮：你打算怎么办？","萨姆：我准备把它摆在这儿，放在窗前。","彭妮：小心点！别摔了！","彭妮：别放在那儿，萨姆。放在这儿，这个架子上。","萨姆：这只漂亮的花瓶。","彭妮：这些花也很漂亮啊。"],words:[{en:"front",cn:"n. 前面"},{en:"in front of",cn:"在……之前"},{en:"careful",cn:"adj. 小心的，仔细的"},{en:"vase",cn:"n. 花瓶"},{en:"drop",cn:"v. 掉下"},{en:"flower",cn:"n. 花"}]},{lesson:41,title:"Penny’s bag",titleCn:"",en:["Is that bag heavy, Penny?","Not very.","Here!","Put it on this chair.","What’s in it?","A piece of cheese.","A loaf of bread.","A bar of soap.","A bar of chocolate.","A bottle of milk.","A pound of sugar.","Half a pound of coffee.","A quarter of a pound of tea.","And a tin of tobacco.","Is that tin of tobacco for me?","Well, it’s certainly not for me!"],zh:["萨姆：那个提包重吗，彭妮？","彭妮：不太重。","萨姆：放在这儿。把它放在这把椅子上。","里面是什么东西？","彭妮：一块乳酪、一块面包、一块肥皂、","一块巧克力、一瓶牛奶、一磅糖、","半磅咖啡、1/4 磅茶叶和一听烟丝。","萨姆：那听烟丝是给我的吗？","彭妮：噢，当然不会给我的！"],words:[{en:"cheese",cn:"n. 乳酪，干酪"},{en:"bread",cn:"n. 面包"},{en:"soap",cn:"n. 肥皂"},{en:"chocolate",cn:"n. 巧克力"},{en:"sugar",cn:"n. 糖"},{en:"coffee",cn:"n. 咖啡"},{en:"tea",cn:"n. 茶"},{en:"tobacco",cn:"n. 烟草，烟丝"}]},{lesson:43,title:"Hurry up!",titleCn:"",en:["Can you make the tea, Sam?","Yes, of course I can, Penny.","Is there any water in this kettle2(水壶)?","Yes, there is.","Where’s the tea?","It’s over there, behind the teapot.","Can you see it?","I can see the teapot, but I can’t see the tea.","There it is!","It’s in front of you.","Ah yes, I can see it now.","Where are the cups?","There are some in the cupboard（碗橱）.","Can you find them?","Yes. Here they are.","Hurry up, Sam.","The kettle’s boiling."],zh:["彭妮：你会沏茶吗，萨姆？","萨姆：会的，我当然会，彭妮。","萨姆：这水壶里有水吗？","彭妮：有水。","萨姆：茶叶在哪儿？","彭妮：就在那儿，茶壶后面。","彭妮：你看见了吗？","萨姆：茶壶我看见了，但茶叶没看到。","彭妮：那不是么！ 就在你眼前。","萨姆：噢，是啊，我现在看到了。","萨姆：茶杯在哪儿呢？","彭妮：碗橱里有几只。","彭妮：你找得到吗？","萨姆：找得到。就在这儿呢。","彭妮：快，萨姆。水开了！"],words:[{en:"of course",cn:"当然"},{en:"kettle",cn:"n. 水壶"},{en:"behind",cn:"prep.在……后面"},{en:"teapot",cn:"n. 茶壶"},{en:"now",cn:"adv. 现在，此刻"},{en:"find",cn:"v. 找到"},{en:"boil",cn:"v. 沸腾，开"}]},{lesson:45,title:"The boss's letter",titleCn:"老板的信",en:["THE BOSS: Can you come here a minute","please, Bob?","BOB: Yes, sir?","THE BOSS: Where's Pamela?","BOB: She's next door.","She's in her office, sir.","THE BOSS: Can she type","this letter for me?","Ask her please.","BOB: Yes, sir.","BOB: Can you type this letter","for the boss please, Pamela?","PAMELA: Yes, of course I can.","BOB: Here you are.","PAMELA: Thank you, Bob.","PAMELA: Bob!","BOB: Yes?","What's the matter.","PAMELA: I can't type this letter.","PAMELA: I can't read it!","The boss's handwriting is","terrible!"],zh:["老 板：请你来一下好吗？鲍勃？","鲍 勃: 什么事，先生？","老 板：帕梅拉在哪儿？","鲍 勃: 她在隔壁，在她的办公室里，先生。","老 板：她能为我打一下这封信吗？请问她。","鲍 勃: 好的，先生。","鲍 勃: 请你把这封信给老板打一下可以吗，","帕梅拉？","帕梅拉：可以，当然可以。","鲍 勃: 给你这信。","帕梅拉：谢谢你，鲍勃。","帕梅拉：鲍勃！","鲍 勃: 怎么了？怎么回事？","帕梅拉：我打不了这封信。","帕梅拉：我看不懂这封信，","老板的书写太糟糕了！"],words:[{en:"can",cn:"modal verb 能够"},{en:"boss",cn:"n. 老板，上司"},{en:"minute",cn:"n. 分（钟）"},{en:"ask",cn:"v. 请求，要求"},{en:"handwriting",cn:"n. 书写"},{en:"terrible",cn:"adj. 糟糕的，可怕的"}]},{lesson:47,title:"A cup of coffee",titleCn:"",en:["MRS YOUNG: Do you like coffee, Mrs Price?","MRS PRICE: Yes, I do.","MRS YOUNG: Do you want a cup?","MRS PRICE: Yes, please. Mrs Young.","MRS YOUNG: Do you want any sugar?","MRS PRICE: Yes, please.","MRS YOUNG: Do you want any milk?","MRS PRICE: No, thank you. I don't like milk in my coffee.","I like black coffee.","MRS YOUNG: Do you like biscuits?","MRS PRICE: Yes, I do.","MRS YOUNG: Do you want one?","MRS PRICE: Yes, please."],zh:["克里斯廷：你喜欢咖啡吗，安？","安：是的，我喜欢。","克里斯廷：你想要一杯吗？","安：好的，请来一杯，克里斯廷。","克里斯廷：你要放些糖吗？","安：好的，请放一些。","克里斯廷：要放些牛奶吗？","安：不了，谢谢。我不喜欢咖啡中放牛奶，我喜欢咖啡。","克里斯廷：你喜欢饼干吗？","安：是的，我喜欢。","克里斯廷：你想要一块吗？","安：好的，请来一块。"],words:[{en:"like",cn:"v. 喜欢，想要"},{en:"want",cn:"v. 想"}]},{lesson:49,title:"At the butcher’s",titleCn:"",en:["BUTCHER: Do you want any meat today.","Mrs. Bird?","MRS.BIRD: Yes, please.","BUTCHER: Do you want beef or lamb?","MRS.BIRD: Beef, please.","BUTCHER: This lamb's very good.","MRS.BIRD: I like lamb,","but my husband doesn't.","BUTCHER: What about some steak?","This is a nice piece.","MRS.BIRD: Give me that piece, please.","MRS.BIRD: And a pound of mince, too.","BUTCHER: Do you want a chicken,","Mrs. Bird?","They 're very nice.","MRS.BIRD: No, thank you.","MRS.BIRD: My husband likes steak,","but he doesn't like chicken.","BUTCHER: To tell you the truth,","Mrs. Bird,","I don't like chicken either!"],zh:["肉    商：您今天要买点肉吗，伯德夫人？","伯德夫人：是的，我买一点。","肉    商：您要牛肉还是要羔羊肉？","伯德夫人：请给我牛肉。","肉    商：这羔羊肉很好。","伯德夫人：我喜欢羔羊肉，可我丈夫不喜欢。","肉    商：来点牛排吗？这块很好。","伯德夫人：就请给我那块吧。","伯德夫人：再来一磅绞肉。","肉    商：您要买只鸡吗，伯德夫人？这些鸡很好。","伯德夫人：不要了，谢谢。","伯德夫人：我丈夫喜欢牛排，但他不喜欢鸡。","肉    商：说老实话，伯德夫人，","我也不喜欢鸡。"],words:[{en:"butcher",cn:"n.   卖肉的"},{en:"meat",cn:"n.   （食用）肉"},{en:"beef",cn:"n.   牛肉"},{en:"lamb",cn:"n.   羔羊肉"},{en:"husband",cn:"n.   丈夫"},{en:"steak",cn:"n.   牛排"},{en:"mince",cn:"n.   肉馅，绞肉"},{en:"chicken",cn:"n.   鸡"},{en:"tell",cn:"v.   告诉"},{en:"truth",cn:"n.   实情"},{en:"either",cn:"adv. 也（用于否定句）"}]},{lesson:51,title:"A pleasant climate",titleCn:"",en:["HANS: Where do you come from?","DIMITRI: I come from Greece.","HANS: What's the climate like in your country?","DIMITRI: It's very pleasant.","Hans: What's the weather like in spring?","DIMITRI: It's often windy in March. It's always warm in April and May, but it rains sometimes.","HANS: What's it like in summer?","DIMITRI: It's always hot in June, July and August. The sun shines every day.","HANS: Is it cold or warm in autumn?","DIMITRI: It's always warm in September and October. It's often cold in November and it rains sometimes.","HANS: Is it very cold in winter?","DIMITRI: It's often cold in December, January and February. It snows sometimes."],zh:["汉 斯：你是哪国人？","迪米特里：我是希腊人。","汉 斯：你们的国家的气候是怎么样？","迪米特里：气候非常宜人。","汉 斯：春季的天气怎么样？","迪米特里：3月里常常刮风。","4月和5月的天气总暖洋洋的，","但有时下雨。","汉 斯：夏季的天气如何呢？","迪米特里：6月、7月和8月的天气总是炎热的","每天都出太阳。","汉 斯：秋季的天气是冷还是暖呢？","迪米特里：9月和10月总是很暖和，","11月常常就冷了，而且有时下雨。","汉 斯：冬季的天气很冷吗？","迪米特里：12月、1月和2月常常很冷，","有时还下雪。"],words:[{en:"Greece",cn:"n. 希腊"},{en:"climate",cn:"n. 气候"},{en:"country",cn:"n. 国家"},{en:"pleasant",cn:"adj. 宜人的"},{en:"weather",cn:"n. 天气"},{en:"spring",cn:"n. 春季"},{en:"windy",cn:"adj. 有风的"},{en:"warm",cn:"adj. 温暖的"},{en:"rain",cn:"v. 下雨"},{en:"sometimes",cn:"adv. 有时"},{en:"summer",cn:"n. 夏天"},{en:"autumn",cn:"n. 秋天"},{en:"winter",cn:"n. 冬天"},{en:"snow",cn:"v. 下雪"},{en:"January",cn:"n. 1月"},{en:"February",cn:"n. 2月"},{en:"March",cn:"n. 3月"},{en:"April",cn:"n. 4月"},{en:"May",cn:"n. 5月"},{en:"June",cn:"n. 6月"},{en:"July",cn:"n. 7月"},{en:"August",cn:"n. 8月"},{en:"September",cn:"n. 9月"},{en:"October",cn:"n. 10月"},{en:"November",cn:"n. 11月"},{en:"December",cn:"n. 12月"}]},{lesson:53,title:"An interesting climate",titleCn:"",en:["in England?","HANS: Where do you come from?","JIM: I come from England.","HANS: What's the climate like in your country?","Jim: It's mild1（温和的）, but it's not always pleasant.","Jim: The weather's often cold in the North and windy in the East. It's often wet in the West and sometimes warm in the South.","Hans: Which seasons do you like best?","Jim: I like spring and summer. The days are long and the nights are short. The sun rises early and sets late. I don't like autumn and winter. The days are short and the nights are long. The sun rises late and sets early. Our climate is not very good, but it's certainly interesting. It's our favorite subject of conversation."],zh:["汉斯：你是哪国人？","吉姆：我是英国人。","汉斯：你们国家的气候怎么样？","吉姆：气候温和，但也不总是宜人的。","吉姆：北部的天气常常寒冷，","东部则常常刮风。","西部常下雨，南部有时则很暖和。","汉斯：你最喜欢哪些季节？","吉姆：我最喜欢春季和夏季。","因为此时白天长而夜晚短，","太阳升得早而落得迟。","虽然我们国家的气候并不很好，","但又确实很有意思。","天气是我们最喜欢谈论的话题"],words:[{en:"mild",cn:"adj. 温和的，温暖的"},{en:"always",cn:"adv. 总是"},{en:"north",cn:"n. 北方"},{en:"east",cn:"n. 东方"},{en:"wet",cn:"adj. 潮湿的"},{en:"west",cn:"n. 西方"},{en:"south",cn:"n. 南方"},{en:"season",cn:"n. 季节"},{en:"best",cn:"adv. 最"},{en:"night",cn:"n. 夜晚"},{en:"rise",cn:"v. 升起"},{en:"early",cn:"adv. 早"},{en:"set",cn:"v. （太阳）落下去"},{en:"late",cn:"adv. 晚，迟"},{en:"interesting",cn:"adj. 有趣的，有意思的"},{en:"subject",cn:"n. 话题"},{en:"conversation",cn:"n. 谈话"}]},{lesson:55,title:"The Sawyer family",titleCn:"",en:["The Sawyers live at 87 King Street.","In the morning, Mr Sawyer goes to work and the children go to school. Their father takes them to school every day.","Mrs Sawyer stays at home every day. She does the housework. She always eats her lunch at noon.","In the afternoon, she usually sees her friends. They often drink tea together.","In the evening, the children come home from school. They arrive home early.","Mr Sawyer comes home from work. He arrives home late.","At night, the children always do their homework. Then they go to bed. Mr Sawyer usually reads his newspaper, but sometimes he and his wife watch television."],zh:["索耶一家住在国王街87号。","早上，索耶先生去上班，孩子们去上学。父亲每天送孩子们去上学。","索耶夫人每天呆在家里。她料理家务。","她总是在正午吃午饭。","下午，她总是会见她的朋友。她们经常在一起喝茶。","傍晚，孩子们放学回家。他们到家很早。","索耶先生下班回家。他到家很晚。","晚上，孩子们总是做作业，然后去睡觉。索耶先生总是读报纸，但有时和他的妻子一起看电视。"],words:[{en:"live",cn:"v. 住，生活"},{en:"stay",cn:"v. 呆在，停留"},{en:"home",cn:"n. 家；"},{en:"",cn:"adv. 到家"},{en:"housework",cn:"n. 家务"},{en:"lunch",cn:"n. 午饭"},{en:"afternoon",cn:"n. 下午"},{en:"usually",cn:"adv. 通常"},{en:"together",cn:"adv. 一起"},{en:"evening",cn:"n. 晚上"},{en:"arrive",cn:"v. 到达"},{en:"night",cn:"n. 夜间"}]},{lesson:57,title:"An unusual day",titleCn:"",en:["It is eight o'clock. The children go to school by car every day, but today, they are going to school on foot.","It is ten o'clock. Mrs Sawyer usually stays at home in the morning, but this morning, she is going to the shops.","It is four o’clock. In the afternoon, Mrs Sawyer usually drinks tea in the living-room, but this afternoon, she is drinking tea in the garden.","It is six o’clock. In the evening, the children usually do their homework, but this evening, they are not doing their homework. At the moment, they are playing in the garden.","It is nine o’clock, Mr. Sawyer usually reads his newspaper at night, but he is not reading his newspaper tonight. At the moment, he is reading an interesting book."],zh:["现在是8点钟。孩子们每天都乘小汽车去上学，而今天，他们正步行上学。","现在是10点钟。上午，索耶夫人通常是呆在家里的，但今天上午，她正去商店买东西。","现在是4点钟，下午，索耶夫人通常是在客厅里喝茶，但今天下午，她正在花园里喝茶。","现在是6点钟。晚上，孩子们通常是做作业，而今天晚上，他们没做作业。此刻，他们正在花园里玩。","现在是9点钟。索耶先生通常是在晚上看报，但今天晚上他没看报。此刻，他正在看一本有趣的书。"],words:[{en:"o'clock",cn:"adv. 点钟"},{en:"shop",cn:"n. 商店"},{en:"moment",cn:"n. 片刻，瞬间"}]},{lesson:59,title:"Is that all?",titleCn:"",en:["LADY: I want some envelopes please.","STATIONER: Do you want the large size, or the small size?","LADY: The large size please.","LADY: Do you have any writing-paper（信纸）?","Stationer: Yes, we do.","Stationer: I don't have any small pads.. I only have large ones. Do you want a pad1（便签簿）?","LADY: Yes, please.","LADY: And I want some black ink and some glue.","Stationer: A bottle of ink and a bottle of glue.","LADY: And I want a large box of chalk, too.","Stationer: I only have small boxes. Do you want one?","LADY: No, thank you.","Stationer: Is that all?","LADY: That's all, thank you.","Stationer: What else do you want?","LADY: I want my change."],zh:["女 士：请给我拿几个信封。","售货员：您要大号的还是小号的？","女 士：请拿大号的。","女 士：您有信纸吗？","售货员：有。","售货员：我没有小本的信纸，只有大本的。","您要一本吗？","女 士：好，请拿一本。","女 士：我还想要黑色墨水和胶水 。","售货员：黑色墨水和胶水。","女 士：我还要一大盒粉笔。","售货员：我只有小盒的。您要一盒吗？","女 士：不了，谢谢。","售货员：就要这些吗？","女 士：就这些，谢谢。","售货员：您还要什么吗？","女 士：我要找的零钱。"],words:[{en:"envelope",cn:"n. 信封"},{en:"writing paper",cn:"信纸"},{en:"shop assistant",cn:"售货员"},{en:"size",cn:"n. 尺寸，尺码，大小"},{en:"pad",cn:"n. 信纸簿"},{en:"glue",cn:"n. 胶水"},{en:"chalk",cn:"n. 粉笔"},{en:"change",cn:"n. 零钱，找给的钱"}]},{lesson:61,title:"A bad cold",titleCn:"",en:["MR WILLIANMS: Where's Jimmy?","MRS WILLIAMS: He's in bed.","MR WILLIAMS: What's the matter with him?","MRS WILLIAMS: He feels ill.","MR WILLIAMS: He looks ill.","MRS WILLIAMS: We must call the doctor.","MR WILLIAMS: Yes, we must.","MR WILLIAMS: Can you remember the doctor's telephone number?","MRS WILLIAMS: Yes. It's 09754.","DOCTOR: Open your mouth, Jimmy. Show me your tongue. Say, 'Ah'.","MR WILLIMAMS: What's the matter with him, doctor?","DOCTOR: He has a bad cold, Mr Williams, so he must stay in bed for a week.","MRS WILLIAMS: That's good news for Jimmy.","DOCTOR: Good news? Why?","MR WILLIAMS: Because he doesn't like school!"],zh:["威廉斯先生：吉米在哪儿？","威廉斯夫人：他躺在床上。","威廉斯先生：他怎么啦？","威廉斯夫人：他觉得不舒服。","威廉斯先生：他看上去是病了。","威廉斯夫人：我们得去请医生。","威廉斯先生：是的，一定得请。","威廉斯先生：你还得医生的电话号码吗？","威廉斯夫人：记得。是09754。","医 生：把嘴张开，吉米。让我们","看看你的舌头。说“啊——”","威廉斯先生：他得了什么病，医生？","医 生：他得了重感冒，威廉斯先生，","因此他必须卧床一周。","威廉斯夫人：对吉米来说，这可是个好消息。","医 生：好消息？为什么？","威廉斯先生：因为他不喜欢上学。"],words:[{en:"feel",cn:"v. 感觉"},{en:"look",cn:"v. 看（起来）"},{en:"must",cn:"modal verb 必须"},{en:"call",cn:"v. 叫，请"},{en:"doctor",cn:"n. 医生"},{en:"telephone",cn:"n. 电话"},{en:"remember",cn:"v. 记得，记住"},{en:"mouth",cn:"n. 嘴"},{en:"tongue",cn:"n. 舌头"},{en:"bad",cn:"adj. 坏的，严重的"},{en:"cold",cn:"n. 感冒"},{en:"news",cn:"n. 消息"}]},{lesson:63,title:"Thank you , doctor.",titleCn:"",en:["DOCTOR: How's Jimmy today?","MRS WILLIAMS: He's better , thank you, doctor.","DOCTOR: Can I see him please, Mrs Williams?","MRS WILLIAMS: Certainly, doctor. Come upstairs.","DOCTOR: You look very well, Jimmy. You are better now, but you mustn't get up yet.","You must stay in bed for another two days.","DOCTOR: The boy mustn't go to school yet, Mrs Williams. And he mustn't eat rich food.","Mrs Williams: Does he have a temperature, doctor?","Doctor: No, he doesn’t.","MRS WILLIAMS: Must he stay in bed?","DOCTOR: Yes. He must remain in bed for another two days. He can get up for about two hours each day, but you must keep the room warm.","DOCTOR: Where's Mr Williams this evening?","MRS WILLIAMS: He's in bed, doctor.","Can you see him, please? He has a bad cold, too!"],zh:["医 生：吉米今天怎么样了？","威廉斯夫人：他好些了。谢谢您，医生。","医 生：我可以看看他吗，威廉斯夫人？","威廉斯夫人：当然可以，医生。上楼吧。","医 生：你看上去很好，吉米。","你现在好些了，但你还不应该起","床。你必须再卧床两天。","医 生：这孩子还不能去上学，","威廉斯夫人，而且不能吃油腻","的食物。","威廉斯夫人：他还发烧吗，医生？","医 生：不，他不发烧了。","威廉斯夫人：他还必须卧床吗？","医 生：是的，他还必须卧床两天。","他每天可以起来两个小时，","但您必须保持房间温暖。","医 生：威廉斯先生今晚去哪儿了？","威廉斯夫人：他在床上呢，医生。","您能看看他吗？","他也得了重感冒！"],words:[{en:"better",cn:"adj. 形容词well的比较级"},{en:"certainly",cn:"adv. 当然"},{en:"get up",cn:"起床"},{en:"yet",cn:"adv. 还，仍"},{en:"rich",cn:"adj. 油腻的"},{en:"food",cn:"n. 食物"},{en:"remain",cn:"v. 保持，继续"}]},{lesson:65,title:"Not a baby",titleCn:"",en:["FATHER: What are you going to do this evening, Jill?","Jill: I'm going to meet some friends, Dad.","FATHER: You mustn't come home late. You must be home at half past ten.","Jill: I can’t get home so early, Dad.","Can I have the key to the front door, please?","FATHER: NO, you can't.","MOTHER: Jill's eighteen years old, Tom. She's not a baby. Give her the key. She always comes home early.","FATHER: Oh, all right!","FATHER: Here you are. But you mustn't come home after a quarter past eleven. Do you hear?","Jill: Yes, Dad.","Jill: Thanks, Mum.","MOTHER: That's all right. Goodbye. Enjoy yourself!","Jill: We always enjoy ourselves, Mum. Bye, bye."],zh:["父亲：今晚你打算干什么，吉尔？","吉尔：我打算去看几个朋友，爸爸。","父亲：你不准回家太晚，你必须在10点半到家。","吉尔：这么早我到不了家，爸爸！","吉尔：我能带上前门的钥匙吗？","父亲：不行， 你不能带。","母亲：吉尔都18岁了，汤姆。她不是小孩子了","把钥匙给她吧。她总早早回家的。","父亲：那么，好吧！","父亲：拿去。但你不能超过11点1刻回家。听","见了吗？","吉尔：听见了，爸爸。","吉尔：谢谢，妈妈。","母亲：不用谢。再见。好好玩吧！","吉尔：我们总是玩得很开心的，妈妈。再见。"],words:[{en:"Dad",cn:"n. 爸（儿语）"},{en:"key",cn:"n. 钥匙"},{en:"baby",cn:"n. 婴儿"},{en:"hear",cn:"v. 听见"},{en:"enjoy",cn:"v. 玩得快活"},{en:"yourself",cn:""},{en:"rpon.",cn:"你自己"},{en:"ourselves",cn:"pron.我们自己"},{en:"mum",cn:"n. 妈妈"}]},{lesson:67,title:"The weekend",titleCn:"",en:["MRS JOHNSON: Hullo, Mrs Williams. Were you at the butcher's?","MRS WILLIAMS: Yes. I was. Were you at the butcher’s ,too?","MRS JOHNSON: No, I wasn’t. I was at the greengrocer’s. How’s Jimmy today?","MRS WILLIAMS: He’s very well, thank you.","MRS JOHNSON: Was he absent from school last week?","MRS WILLIAMS: Yes, he was. He was absent on Monday, Tuesday, Wednesday and Thursday. How are you all keeping?（你们身体怎么样？）","MRS JOHNSON: Very well, thank you. We’re going to spend three days in the country. We’re going to stay at my mother’s for the week-end.","MRS WILLIAMS: Friday, Saturday and Sunday in the country! Aren’t you lucky!"],zh:["约翰逊夫人：您好。刚才您在肉店里吗？","威廉斯夫人：是的，我在肉店里。","您也在肉店里吗？","约翰逊夫人：不， 我不是。","我在蔬菜水果店里。","吉米今天怎么样？","威廉斯夫人：他很好，谢谢您。","约翰逊夫人：上星期他没上学吧？","威廉斯夫人：是的，他没上学。他星期一、","星期二、星期三和星期四没","去上学。你们身体都好吗？","约翰逊夫人：很好，谢谢您。我们打算到","乡下去三天，在我母亲家度","周末。","威廉斯夫人：星期五、星期六和星期日在乡下","过！你们真幸运啊！"],words:[{en:"greengrocer",cn:"n. 蔬菜水果零售商"},{en:"absent",cn:"adj. 缺席的"},{en:"Monday",cn:"n. 星期一"},{en:"Tuesday",cn:"n. 星期二"},{en:"Wednesday",cn:"n. 星期三"},{en:"Thursday",cn:"n. 星期四"},{en:"keep",cn:"v. （身体健康）处于（状况）"},{en:"spend",cn:"v. 度过"},{en:"weekend",cn:"n. 周末"},{en:"Friday",cn:"n. 星期五"},{en:"Saturday",cn:"n. 星期六"},{en:"Sunday",cn:"n. 星期日"},{en:"country",cn:"n. 乡村"},{en:"lucky",cn:"adj. 幸运的"}]},{lesson:69,title:"The car race",titleCn:"",en:["There is a car race near our town every year. In 1995, there was a very big race.","There were hundreds of people there. My wife and I were at the race. Our friends, Julie and Jack were there, too. You can see us in the crowd. We are standing on the left.","There were twenty cars in the race. There were English cars, French cars, German cars, Italian cars, American cars and Japanese cars.","It was an exciting finish. The winner was Billy Stewart. He was in car number fifteen. Five other cars were just behind him.","On the way home, my wife said to me, “Don’t drive so quickly! You’re not Billy Stewart!”"],zh:["在我们镇子附近每年都有一场汽车比赛。1995年举行了一次盛大的比赛。","许许多多人都去了赛场。我和我的妻子也去了。我们的朋友朱莉和杰克也去了。你可以在人群中看到我们。我们站在左面。","参加比赛的有20辆汽车。有英国、法国、德国、意大利、美国和日本的汽车。","比赛的结尾是激动人心的。获胜者是比利.斯图尔特。他在第15号车里，其他5辆汽车跟在他后面。","在回家的途中，我妻子对我说：“别开得这样快！你可不是比利.斯图尔特！”","练习答案  Key to written exercises"],words:[{en:"year",cn:"n. 年"},{en:"race",cn:"n. 比赛"},{en:"town",cn:"n. 城填"},{en:"crowd",cn:"n. 人群"},{en:"stand",cn:"v. 站立"},{en:"exciting",cn:"adj. 使人激动的"},{en:"just",cn:"adv. 正好，恰好"},{en:"finish",cn:"n. 结尾，结束"},{en:"winner",cn:"n. 获胜者"},{en:"behind",cn:"prep.在……之后"},{en:"way",cn:"n. 路途"}]},{lesson:71,title:"He’s awful",titleCn:"",en:["Jane : What’s Ron Marston like , Pauline ?","Pauline : He’s awful ! He telephoned me four times yesterday , and three times the day before yesterday.","Pauline: He telephoned the office yesterday morning and yesterday afternoon. My boss answered the telephone .","Jane : What did your boss say to him ?","Pauline: He said ,”Pauline is typing letters .She can’t speak to you now !”","Pauline : Then I arrived home at six o’clock yesterday evening .He telephoned again .But I didn’t answer the phone !","Jane : Did he telephone again last night ?","Pauline : Yes , he did . He telephoned at nine o’clock .","Jane : What did you say to him ?","Pauline : I said ,”This is Pauline ‘s mother . Please don’t telephone my daughter again !”","Jane : Did he telephone again ?","Pauline : No , he didn’t !"],zh:["简：罗恩.马斯顿是怎样一个人？","波淋：他讨厌透了！他昨天给我打了4次电话","前天打了3次。","波淋：他昨天上午和下午把电话打到了我的","办公室，是我的老板接的。","简：你老板是怎么对他说的？","波淋：他说：“波淋正在打信，她现在不能","同你讲话！”","波淋：后来，我昨晚6点钟回到家里。","他又打来电话，但我没接。","简：他昨夜里又打电话了吗？","波淋：是的，打了。他在9点钟又打电话。","简：你对他怎么说的？","波淋：我说：“我是波淋的母亲。","请不要再给我女儿打电话了！”","简：他又打了没有？","波淋：没有！"],words:[{en:"awful",cn:"adj. 让人讨厌的，坏的"},{en:"telephone",cn:"v. & n. 打电话；电话"},{en:"time",cn:"n. 次（数）"},{en:"answer",cn:"v. 接（电话）"},{en:"last",cn:"adj. 最后的，前一次的"},{en:"phone",cn:"n. 电话（=telephone）"},{en:"again",cn:"adv. 又一次地"},{en:"say (said/sed/)",cn:"v. 说"}]},{lesson:73,title:"The way to King Street",titleCn:"",en:["Last week Mrs Mills went to London. She does not know London very well, and she lost her way.","Suddenly, she saw a man near a bus-stop. “ I can ask him the way.” She said to herself.","“Excuse me,” she said.","“Can you tell me the way to King Street please?”","The man smiled pleasantly. He did not understand English! He spoke German. He was a tourist.","Then he put his hand into his pocket, and took out a phrase-book.","He opened the book and found a phrase. He read the phrase slowly.","“I am sorry,” he said. “ I do not speak English.”"],zh:["上星期米尔斯夫人去了伦敦。她对伦敦不很熟悉，因此迷了路。","突然，她在公共汽车站附近看到一个男人。“我可以向他问路，”她想。","“对不起，您能告诉我到国王街怎么走吗？”她说。","这人友好地笑了笑。他不懂英语！他讲德语。他是个旅游者。","然后他把手伸进了衣袋，掏出了一本常用语手册。","他翻开书找到了一条短语。他缓慢地读着短语。","”很抱歉，“他说，”我不会讲英语。”"],words:[{en:"week",cn:"n. 周"},{en:"London",cn:"n. 伦敦"},{en:"suddenly",cn:"adv. 突然地"},{en:"bus stop",cn:"公共汽车站"},{en:"smile",cn:"v. 微笑"},{en:"pleasantly",cn:"adv. 愉快地"},{en:"understand (understood)",cn:"v. 懂，明白"},{en:"speak (spoke)",cn:"v. 讲，说"},{en:"hand",cn:"n. 手"},{en:"pocket",cn:"n. 衣袋"},{en:"phrasebook",cn:"n. 短语手册，常用语手册"},{en:"phrase",cn:"n. 短语"},{en:"slowly",cn:"adv. 缓慢地"}]},{lesson:75,title:"Uncomfortable shoes",titleCn:"",en:["LADY : Have you any shoes like these?","SALESMAN: What size?","Lady: Size five.","Salesman: What colour?","Lady: Black.","Salesman: I’m sorry. We don't have it.","Lady: But my sister bought this pair last month.","Salesman: Did she buy them here?","Lady: No, she bought them in the U.S.","Salesman: We had some shoes like those a month ago, but we haven’t any now.","Lady: Can you get a pair for me please?","Salesman: I’m afraid that I can’t. They were in fashion last year and the year before last.","But they’re not in fashion this year.","Salesman: These shoes are in fashion now.","Lady: They look very uncomfortable.","Salesman: They are very uncomfortable. But women always wear uncomfortable shoes!"],zh:["女 士：像这样的鞋子你们有吗？","售货员：什么尺码的？","女 士：5号的。","售货员：什么颜色？","女 士：黑的","售货员：对不起，我们没有。","女 士：但是，我姐姐上个月买到了这样的","一双。","售货员：她是在这儿买的吗？","女 士：不。她是在美国买的。","售货员：一个月前我们有这样的鞋。","但是现在没有了。","女 士：您能为我找一双吗？","售货员：恐怕不行。这鞋在去年和前年时兴，","而今年已不流行了。","售货员：现在流行的是这种鞋子。","女 士：这种鞋子看上去很不舒适。","售货员：的确很不舒适。可是女人们总是","穿不舒适的鞋子！"],words:[{en:"ago",cn:"adv. 以前"},{en:"buy(bought)",cn:"v. 买"},{en:"pair",cn:"n. 双，对"},{en:"fashion",cn:"n. （服装的）流行式样"},{en:"uncomfortable",cn:"adj. 不舒服的"},{en:"wear",cn:"v. 穿着"}]},{lesson:77,title:"Terrible toothache",titleCn:"",en:["Nurse: Good morning, Mr Croft.","Mr Croft: Good morning, nurse. I want to see the dentist, please.","Nurse: DO you have an appointment?（有预约吗？）","Mr Croft: No, I don't .","Nurse: Is it urgent?","Mr Croft: Yes, it is . It’s very urgent. I feel awful. I have a terrible toothache.","Nurse: Can you come at 10 am on Monday, April 24th?","Mr Croft: I must see the dentist now, nurse.","Nurse: The dentist is very busy at the moment. Can you come at 2:00 PM?","Mr Croft: That’s very late. Can’t the dentist see me now?","Nurse: I’m afraid that he can’t , Mr Croft. Can’t you wait till this afternoon?","Mr Croft: I can wait, but my toothache can’t !"],zh:["护 士：早上好，克罗夫特先生。","克罗夫特先生：早上好，护士。我想见牙科","医生。","护 士：您约好了吗？","克罗夫特先生：没有。","护 士：急吗？","克罗夫特先生：是的，很急。我难受极了，","牙痛得要命。","护 士：您在4月24日星期一上午10点","钟来行吗？","克罗夫特先生：我必须现在就见牙科医生，","护士。","护 士：牙科医生这会儿很忙。","您下午两点钟来行吗？","克罗夫特先生：那就太晚了。牙科医生现在","就不能给我看一下吗？","护 士：恐怕不能，克罗夫特先生。","您就不能等到今天下午吗？","克罗夫特先生：我倒是可以等。","可是我的牙痛等不了啊！"],words:[{en:"appointment",cn:"n. 约会，预约"},{en:"urgent",cn:"adj. 紧急的，急迫的"},{en:"utill",cn:"prep.直到……为止"}]},{lesson:79,title:"Peggy’s shopping-list",titleCn:"",en:["Tom: What are you doing, Peggy?","Peggy: I’m making a shopping-list, Tom.","Tom: What do we need?","Peggy: We need a lot of things this week.","Peggy: I must go to the grocer’s. We haven’t got much tea or coffee, and we haven’t got any sugar or jam.","Tom: What about vegetables?","Peggy: I must go to the greengrocer’s. We haven’t got many tomatoes, but we’ve got a lot of potatoes.","Peggy: I must go to the butcher’s, too. We need some meat. We haven’t got any meat at all.","Tom: Have we got any beer and wine?","Peggy: No, we haven’t. And I’m not going to get any!","Tom: I hope that you’ve got some money.","Peggy: I haven’t got much.","Tom: Well, I haven’t got much either!"],zh:["汤 姆：卡罗尔，你在干什么？","卡罗尔：我在写购物单，汤姆。","汤 姆：我们都需要什么？","卡罗尔：这星期我们需要很多东西。","卡罗尔：我得去一下食品店。我们的茶叶和","咖啡不多了，糖和果酱也没有了。","汤 姆：蔬菜呢？","卡罗尔：我还得到蔬菜水果店去一下。我们","番茄不多了，但土豆还有不少。","卡罗尔：我还要到肉店去一下。我们","需要些肉。我们一点肉也没有了。","汤 姆：我们还有啤酒和葡萄酒吗？","卡罗尔：没有了。不过，我不打算去买！","汤 姆：我希望你还有钱。","卡罗尔：我的钱不多了。","汤 姆：唉，我也不多了。"],words:[{en:"shopping",cn:"n. 购物"},{en:"list",cn:"n. 单子"},{en:"vegetable",cn:"n. 蔬菜"},{en:"need",cn:"v. 需要"},{en:"hope",cn:"v. 希望"},{en:"thing",cn:"n. 事情"},{en:"money",cn:"n. 钱"}]},{lesson:81,title:"Roast beef and potato.",titleCn:"",en:["John: Hello, Peggy! Where’s Tom?","Peggy: He’s upstairs. He’s having a bath.","Peggy: Tom!","Tom: Yes?","Peggy: John’s here.","Tom: I’m nearly ready.","Tom: Hello, John. Have a cigarette.","John: No thanks, Tom.","Tom: Have a glass of whisky then.","John: O.K. Thanks.","Tom: Is dinner ready, Peggy?","Peggy: It’s nearly ready. We can have dinner at seven o’clock.","Tom: John and I had lunch together today. We went to a restaurant.","Peggy: What did you have?","Tom: We had roast beef and potatoes.","Peggy: Oh!","Tom: What’s the matter, Peggy?","Peggy: Well, you’re going to have roast beef and potatoes again tonight!"],zh:["萨 姆：你好，卡罗尔！汤姆在哪儿？","卡罗尔：他在楼上。他正在洗澡。","卡罗尔：汤姆！","汤 姆：什么事？","卡罗尔：萨姆来了。","汤 姆：我马上就好。","汤 姆：你好，萨姆。请抽烟。","萨 姆：不，谢谢，汤姆。","汤 姆：那么，来杯威士忌吧。","萨 姆：好的，谢谢。","汤 姆：卡罗尔，饭好了吗？","卡罗尔：马上就好。7点钟我们可以吃饭。","汤 姆：我和萨姆今天一起吃的午饭。","我们去了一家饭店。","卡罗尔：你们吃了什么？","汤 姆：我们吃的是烤牛肉和土豆。","卡罗尔：噢！","汤 姆：怎么了，卡罗尔？","卡罗尔：唉，今晚你们又要吃烤牛肉","和土豆了！"],words:[{en:"bath",cn:"n. 洗澡"},{en:"nearly",cn:"adv. 几乎，将近"},{en:"ready",cn:"adj. 准备好的，完好的"},{en:"dinner",cn:"n. 正餐，晚餐"},{en:"roast",cn:"adj. 烤的"}]},{lesson:83,title:"Going on a holiday",titleCn:"",en:["Peggy: Hello, John. Come in.","Tom: Hello, John. We’re having lunch. Do you want to have lunch with us?","John: No thank you, Tom. I’ve already had lunch. I had lunch at half past twelve.","Peggy: Have a cup of coffee then.","John: I’ve just had a cup, thank you. I had one after my lunch.","Tom: Let’s go into the living-room, Peggy. We can have our coffee there.","Peggy: Excuse the mess, John. This room’s very untidy. We’re packing our suitcases. We’re going to leave tomorrow. Tom and I are going to have a holiday.","John: Aren’t you lucky!","Tom: When are you going to have a holiday, John?","John: I don’t know. I’ve already had my holiday this year.","Peggy: Where did you go?","John: I stayed at home!"],zh:["卡罗尔：你好，萨姆。进来吧。","汤 姆：你好，萨姆。我们正在吃午饭，","你跟我们一起吃午饭好吗？","萨 姆：不，汤姆，谢谢。我已经吃过饭了。","我在12点半吃的。","卡罗尔：那么喝杯咖啡吧。","萨 姆：我刚喝了一杯，谢谢。","我是在饭后喝的。","汤 姆：我们到客厅里去吧，","卡罗尔。我们可以在那里喝咖啡。","卡罗尔：屋子很乱，请原谅，萨姆。","我们正在收拾手提箱。明天我们就要走了。","我和汤姆准备去度假。","萨 姆：你们真幸运！","汤 姆：萨姆，你准备什么时候去度假？","萨 姆：我不知道。今年我已度过假了。","卡罗尔：你去哪儿了？","萨 姆：我呆在家里了！"],words:[{en:"mess",cn:"n. 杂乱，凌乱"},{en:"pack",cn:"v. 包装，打包，装箱"},{en:"suitcase",cn:"n. 手提箱"},{en:"leave",cn:"v. 离开"},{en:"already",cn:"adv. 已经"}]},{lesson:85,title:"Paris in the Spring",titleCn:"",en:["George: Hello, Ken.","Ken: Hello, George.","George: Have you just been to the cinema?","Ken: Yes, I have.","George: What’s on?","Ken: “Paris in the Spring”.","George: Oh, I’ve already seen it.I saw it on television last year. It’s an old film, but it’s very good.","Ken: Paris is a beautiful city.","George: I have never been there. Have you ever been there, Ken?","Ken: Yes, I have. I was there in April.","George: Paris in the spring, eh?","Ken: It was spring, but the weather was awful. It rained all the time.","George: Just like London!"],zh:["乔治：你好，肯。","肯：你好，乔治。","乔治：你刚去过电影院吗？","肯：是的，我刚去过。","乔治：上映什么片子？","肯：《巴黎之春》。","乔治：噢，我已看过了。","我是去年在电视上看的。","这是老部片子，但很好。","肯：巴黎是座美丽的城市。","乔治：我从未去过。肯，你去过吗？","肯：是的，我去过。4月份我在那儿。","乔治：那是巴黎之春，是吗？","肯：是春天，但天气太糟了。","一直在下雨。","乔治：就像伦敦一样！"],words:[{en:"Paris",cn:"n. 巴黎"},{en:"cinema",cn:"n. 电影院"},{en:"film",cn:"n. 电影"},{en:"beautiful",cn:"adj. 漂亮的"},{en:"city",cn:"n. 城市"},{en:"never",cn:"adv. 从来没有"},{en:"ever",cn:"adv. 在任何时候"}]},{lesson:87,title:"A car crash",titleCn:"",en:["Mr Wood: Is my car ready yet?","Attendant2: I don’t know, sir. What’s the licence number of your car?","Mr Wood: It’s LFZ 312 G.","Attendant: When did you bring it to us?","Mr Wood: I brought it here three days ago.","Attendant: Ah yes, I remember now.","Mr Wood: Have your mechanics finished yet?","Attendant: No, they’re still working on it. Let’s go into the garage and have a look at it.","Attendant: Isn’t that your car?","Mr Wood: Well, it was my car.","Attendant: Didn’t you have a crash?","Mr Wood: That’s right. I drove it into a lamp post（电线杆）. Can your mechanics repair it?","Attendant: Well, they’re trying to repair it, sir. But to tell you the truth, you need a new car."],zh:["伍德先生：我的汽车修好了吗？","服 务 员：我不知道，先生。","您的汽车牌号是多少？","伍德先生：是 LFZ312G。","服 务 员：您什么时候送来的？","伍德先生：3天前。","服 务 员：啊，是的，我现在记起来了。","伍德先生：你们的机械师修好了吗？","服 务 员：没有，他们还在修呢。","我们到车库去看一下吧。","服 务 员：这难道不是您的车吗？","伍德先生：唔，这曾是我的车。","服 务 员：难说您没有出车祸吗？","伍德先生：是啊。我把汽车撞在电线杆上了。","你们的机械师能修好吗？","服 务 员：啊，他们正设法修呢，先生。","不过说实在的，您需要一辆","新车了。","【生词】","attendant                                           n. 接待员","bring(brought, brought)                       v. 带来，送来","garage                                               n. 车库，汽车修理厂","crash                                                 n. 碰撞","lamp-post                                          灯杆","repair                                                v. 修理","try                                                    v. 努力，设法"],words:[{en:"attendant",cn:"n. 接待员"},{en:"bring(brought, brought)",cn:"v. 带来，送来"},{en:"garage",cn:"n. 车库，汽车修理厂"},{en:"crash",cn:"n. 碰撞"},{en:"lamp-post",cn:"灯杆"},{en:"repair",cn:"v. 修理"},{en:"try",cn:"v. 努力，设法"}]},{lesson:89,title:"For sale",titleCn:"",en:["Mr Hill: Good afternoon. I believe that this house is for sale（待售）.","Mr West: That’s right.","Mr Hill: May I have a look at it please?","Mr West: Yes, of course. Come in.","Mr Hill: How long have you lived here?","Mr West: I have lived here for twenty years.","Mr Hill: Twenty years! That’s a long time.","Mr West: Yes, I have been here since 1947.","Mr Hill: Then why do you want to sell it?","Mr West: Because I have just retired. I want to buy a small house in the country.","Mr Hill: How much does this house cost?","Mr West: ￡6850.","Mr Hill: That’s a lot of money!","Mr West: It’s worth every penny of it.","Mr Hill: Well, I like the house, but I can’t decide yet. My wife must see it first.","Mr West: Women always have the last word."],zh:["奈杰尔：下午好。我想这房子是要出售的吧！","伊 恩: 是的。","奈杰尔：我可以看一看吗？","伊 恩: 可以，当然可以。请进。","奈杰尔：您在这里住了多长时间？","伊 恩: 我在这里住了20年了。","奈杰恩：20年！这个时间可不短。","伊 恩: 是啊，从1976年起我就住在这里。","奈杰尔：那么，您为什么要卖掉它呢？","伊 恩: 因为我刚退休。","我想在乡下买幢小房子。","奈杰尔: 这座房子卖多少钱？","伊 恩: 68,500英镑。","奈杰尔：这可真是一大笔钱呢！","伊 恩: 它确确实实值这么多钱。","奈杰尔：啊，我喜欢这房子，","但我还不能决定。","我妻子必须先来看一看。","伊 恩: 女人总是最后说了算的。"],words:[{en:"believe",cn:"v. 相信，认为"},{en:"may",cn:"modal verb5 （用于请求许可）可以"},{en:"how long",cn:"多长"},{en:"since",cn:"prep.自从"},{en:"why",cn:"adv. 为什么"},{en:"sell (sold, sold)",cn:"v. 卖，出售"},{en:"because",cn:"conj.因为"},{en:"retire1",cn:"v. 退休"},{en:"cost (cost, cost)",cn:"v. 花费"},{en:"pound",cn:"n. 英镑"},{en:"worth",cn:"prep.值……钱"},{en:"penny",cn:"n. 便士"}]},{lesson:91,title:"Poor West",titleCn:"",en:["Mrs Smith: Has Mr West sold his house yet?","Mrs Brown: Yes, he has. He sold it last week.","Mrs Smith: Has he moved to his new house yet?","Mrs Brown: No, not yet. He’s still here. He’s going to move tomorrow.","Mrs Smith: When? Tomorrow morning?","Mrs Brown: No. Tomorrow afternoon. I’ll miss him. He has always been a good neighbour.","Mrs Green: He’s a very nice person. We shall all miss him.","Mrs Smith; When will the new people move into this house?","Mrs Brown: I think that they will move in the day after tomorrow.","Mrs Green: Will you see Mr West today, Mrs Brown?","Mrs Brown: Yes, I will.","Mrs Green: Please give him my regards. （give one’s regards to sb.向sb.问候）","Mr Smith: Poor Mr West! He didn’t want to leave this house.","Mrs Brown: No, he didn’t want to leave, but his wife did!"],zh:["凯瑟琳：伊恩已指他的房子卖掉了吗？","詹 尼：是的，卖掉了。他上星期卖掉的。","凯瑟琳：他已经迁进新居了吗？","詹 尼：不，还没有。他仍在这里。","他打算明天搬家。","凯瑟琳：什么时候？明天上午吗？","詹 尼：不，明天下午。我会想念他的。","他一直是个好邻居。","琳 达：他是个非常好的人，","我们大学都会想念他的。","凯瑟琳：新住户什么时候搬进这所房子？","詹 尼：我想他们将会在后天搬进来吧。","琳 达：詹尼，您今天会见到伊恩吗？","詹 尼：是的，我会见到他。","琳 达：请代我问候他。","凯瑟琳：可怜的伊恩！他本不想离开这幢","房子。","詹 尼：是啊，他是不想离开，","可是他妻子要离开。"],words:[{en:"still",cn:"adv. 还，仍旧"},{en:"move",cn:"v. 搬家"},{en:"miss",cn:"v. 想念，思念"},{en:"neighbor",cn:"n. 邻居"},{en:"person",cn:"n. 人"},{en:"people",cn:"n. 人们"},{en:"poor",cn:"adj. 可怜的"}]},{lesson:93,title:"Our new neighbor",titleCn:"",en:["Mr Hill is our new next-door neighbour. He’s a pilot.","He was in the R.A.F.(皇家空军)","He will fly to New York next month.","The month after next he will fly to Tokyo.","At the moment（现在）, he’s in Madrid. He flew to Spain a week ago.","He will return to London the week after next.","He’s only forty-one years old, and he has already been to nearly every country in the world.","Mr Hill is a very lucky man. But his wife isn’t very lucky. She usually stays at home!"],zh:["奈杰尔是我们新搬来的隔壁邻居。他是个飞行员。","他曾在皇家空军任职。","下个月他将飞往纽约。","再下个月他将飞往东京。","现在他在马德里。他是一星期以前飞到西班牙的。","再下个星期他将返回伦敦。","他只有41岁，但他却过世界上几乎每一个国家。","奈杰尔是个很幸运的人。但他的妻子运气不很好。他总是呆在家里！"],words:[{en:"pilot",cn:"n. 飞行员"},{en:"return",cn:"v. 返回"},{en:"New York",cn:"n. 纽约"},{en:"Tokyo",cn:"n. 东京"},{en:"Madrid",cn:"n. 马德里"},{en:"fly (flew, flown)",cn:"v. 飞行"}]},{lesson:95,title:"Ticket, please.",titleCn:"",en:["George: Two return tickets to London please. What time will the next train leave?","Attendant: At nineteen minutes past eight.","George: Which platform?","Attendant: Platform Two. Over the bridge.","Ken: What time will the next train leave?","George: At eight nineteen.","Ken: We’ve got plenty of time.","George: It’s only three minutes to eight.","Ken: Let’s go and have a drink. There’s a bar next door to the station.","George: We had better go back to the station now, Ken.","Porter2: Tickets please.","George: We want to catch the eight nineteen to London.","Porter: You’ve just missed it!","George: What! It’s only eight fifteen.","Porter: I’m sorry, sir. That clock’s ten minutes slow.","George: When’s the next train?","Porter: In five hours’ time!"],zh:["乔 治：买两张到伦敦的往返票。","下一班火车什么时候开？","服务员：8点19分。","乔 治：在哪个站台？","服务员：2号站台。过天桥。","肯：下一班火车什么时候开？","乔 治：8点19分。","肯：我们时间还很宽裕。","乔 治：现在才7点57分。","肯：让我们去喝点东西吧，","车站旁有一个酒吧。","乔 治：肯，我们现在最好回车站去。","收票员：请把车票拿出来。","乔 治：我们要乘8点19分的车去伦敦。","收票员：你们刚好错过了那班车。","乔 治：什么！现在只有8点15分。","收票员：对不起，先生，那个钟慢了10分钟。","乔 治：下一班车是什么时候？","收票员：5个小时以后！"],words:[{en:"return",cn:"n. 往返"},{en:"train",cn:"n. 火车"},{en:"platform",cn:"n. 站台"},{en:"plenty",cn:"n. 大量"},{en:"bar",cn:"n. 洒吧"},{en:"station",cn:"n. 车站，火车站"},{en:"porter",cn:"n. 收票员"},{en:"catch (caught, caught)",cn:"v. 赶上"},{en:"miss",cn:"v. 错过"}]},{lesson:97,title:"A small blue case",titleCn:"",en:["Mr Hall: I left a suitcase on the train to London the other day.","Attendant: Can you describe it, sir?","Mr Hall: It’s a small blue case and it’s got a zip. There’s a label on the handle with my name and address on it.","Attendant: Is this case yours?","Mr Hall: No, that’s not mine.","Attendant: What about this one? This one’s got a label.","Mr Hall: Let me see it.","Attendant: What’s your name and address?","Mr Hall: David Hall,","83, Bridge Street.","Attendant: That’s right.","D.N.Hall.","83.Bridge Street.","Attendant: Three pound and fifty pence please.","Mr Hall: Here you are.","Attendant: Thank you.","Mr Hall: Hey!","Attendant: What’s the matter?","Mr Hall: This case doesn’t belong to me! You’ve given me the wrong case!"],zh:["霍尔先生：几天前我把一只手提箱忘在","开往伦敦的火车上了。","服 务 员：先生，您能描述一下它是什么","样子的吗？","霍尔先生：是只蓝色的小箱子，上面有拉链。","箱把上有一标签，","上面写着我的姓名和住址。","服 务 员：这箱子是您的吗？","霍尔先生：不，那不是我的。","服 务 员：这只是不是？这只箱子有张标签。","霍尔先生：让我看看。","服 务 员：您的姓名和住址？","霍尔先生：大卫.霍尔，大桥街83号。","服 务 员：那就对了。D.N.霍尔，","大桥街83号。","服 务 员：请付3英镑50便士。","霍尔先生：给您。","服 务 员：谢谢您。","霍尔先生：嗨！","服 务 员：怎么回事？","霍尔先生：这箱子不是我的！您给错了！"],words:[{en:"leave (left, left)",cn:"v. 遗留"},{en:"describe",cn:"v. 描述"},{en:"zip",cn:"n. 拉链"},{en:"label",cn:"n. 标签"},{en:"handle",cn:"n. 提手，把手"},{en:"address",cn:"n. 地址"},{en:"pence",cn:"n. penny4 的复数形式"},{en:"belong",cn:"v. 属于"}]},{lesson:99,title:"Ow!",titleCn:"",en:["Ted : Ow!","Pat2: What’s the matter, Ted?","Ted: I slipped and fell downstairs.","Pat: Have you hurt yourself?","Ted: Yes, I have. I think that I’ve hurt my back.","Pat: Try and stand up. Can you stand up?","Here. Let me help you.","Ted: I’m sorry, Pat. I’m afraid that I can’t get up.","Pat: I think that the doctor had better see you. I’ll telephone Dr Carter.","Pat: The doctor says that he will come at once. I’m sure that you need an X-ray, Ted."],zh:["安迪：啊哟！","露西：怎么了，安迪？","安迪：我滑了一跤，从楼梯上摔下来了。","露西：你摔伤了没有？","安迪：是啊，摔伤了。我想我把背摔坏了。","露西：试试站起来。你能站起来吗？","来，让我帮你。","安迪：对不起，露西，恐怕我站不起来。","露西：我想最好请医生来给你看一下。","我去给卡特医生打电话。","露西：医生说他马上就来。安迪，","我看你需要做一次X光透视。"],words:[{en:"own",cn:"int. 哎哟"},{en:"slip",cn:"v. 滑倒，滑了一脚"},{en:"fall (fell, fallen)",cn:"v. 落下，跌倒"},{en:"downstairs",cn:"adv. 下楼"},{en:"hurt (hurt, hurt)",cn:"v. 伤，伤害，疼痛"},{en:"back",cn:"n. 背"},{en:"stand up",cn:"起立，站起来"},{en:"help",cn:"v. 帮助"},{en:"at once",cn:"立即"},{en:"sure",cn:"adj. 一定的，确信的"},{en:"X-ray",cn:"n. X光透视"}]},{lesson:101,title:"A card from Jimmy",titleCn:"",en:["Grandmother: Read Jimmy’s card to me please, Mary.","Mary: “I have just arrived in Scotland and I’m staying at a Youth Hostel.”","Grandmother: Eh?","Mary: He says he’s just arrived in Scotland. He says he’s staying at a Youth Hostel.","You know he’s a member of the Y.H.A.","Grandmother: The what?","Mary: The Y.H.A., mother. The Youth Hostel’s Association.","Grandmother: What else does he say?","Mary: “I’ll write a letter soon. I hope you are all well.”","Grandmother: What? Speak up, Mary. I’m afraid I can’t hear you.","Mary: He says he’ll write a letter soon. He hopes we are all well. “ Love, Jimmy.”","Grandmother: Is that all? He doesn’t say very much, does he?","Mary: He can’t write very much on a card, mother."],zh:["祖母：请把吉米的明信片念给我听听，彭妮。","彭妮：“我刚到苏格兰，我现住在一家青年","招待所。”","祖母：什么？","彭妮：他说他刚到苏格兰。他说他住在一家","青年招待所。你知道，他是“青招协”","的一个成员。","祖母：什么？","彭妮：“青招协”，妈妈。青年招待所协会。","祖母：他还说了些什么？","彭妮：“我很快会写信的。","祝你们大家身体都好。”","祖母：什么？彭妮，大声一点。","我可听不见你念的。","彭妮：他说他很快会写信的。他祝我们大家","身体好。“谨此问候，吉米。”","祖母：就这些吗？他没写许多，是吗？","彭妮：在明信片上他写不了很多，妈妈。"],words:[{en:"Scotland",cn:"n. 苏格兰（英国）"},{en:"card",cn:"n. 明信片"},{en:"youth",cn:"n. 青年"},{en:"hostel",cn:"n. 招待所，旅馆"},{en:"association",cn:"n. 协会"},{en:"soon",cn:"adv. 不久"},{en:"write (wrote, written)",cn:"v. 写"}]},{lesson:103,title:"The Intelligence test",titleCn:"",en:["Harry1: How was the examination, Dick?","Dick: Not too bad. I think I passed in English and Mathematics. The questions were very easy. How about you, Harry?","Harry: The English and Maths papers weren’t easy enough for me. I hope I haven’t failed.","Dick: I think I failed the Intelligence Test. I could answer sixteen of the questions.","They were very easy. But I couldn't answer the rest. They were too difficult for me.","Harry: Intelligence tests are awful, aren’t they?","Dick: I hate them. I’m sure I’ve got a low I.Q.","Harry: Oh, cheer up（振作点）! Perhaps we didn’t do too badly.","The guy next to me wrote his name at the top of the paper.","Dick: Yes?","Harry: Then he sat there and looked at it for three hours! He didn’t write a word!"],zh:["加 里：考试考得怎样，理查德？","理查德：不算太坏，我想我的英语和数学","及格了。题目很容易。加里，","你怎么样？","加 里：英语和数学试题对我来说不很容易。","我希望别不及格。","理查德：我想我的法语及不了格，我能回答","其中的16道题。这些题很容易。","但我回答不出其作的题。那些题对","我来说太难了。","加 里：法语太可怕了，你说呢？","理查德：我讨厌法语。我的法语成绩肯定","很低。","加 里：啊，别灰心！或许我们考得还不太","糟。坐在我旁边的那个人只在试卷","顶端写自己的名字。","理查德：是吗？","加 里：然后他就坐在那里，对着考卷看了3","个小时，一个字也没写！"],words:[{en:"exam",cn:"n. 考试"},{en:"pass",cn:"v. 及格，通过"},{en:"mathematics (maths",cn:"是缩写)"},{en:"",cn:"n. 数学"},{en:"question",cn:"n. 问题"},{en:"easy",cn:"adj. 容易的"},{en:"enough",cn:"adv. 足够地"},{en:"paper",cn:"n. 考卷"},{en:"fail",cn:"v. 未极格，失败"},{en:"answer",cn:"v. 回答"},{en:"mark",cn:"n. 分数"},{en:"rest",cn:"n. 其他的东西"},{en:"difficult",cn:"adj. 困难的"},{en:"hate",cn:"v. 讨厌"},{en:"low",cn:"adj. 低的"},{en:"cheer",cn:"v. 振作，振奋"},{en:"guy",cn:"n. 家伙，人"},{en:"top",cn:"n. 上方，顶部"}]},{lesson:105,title:"Full of mistakes",titleCn:"",en:["THE BOSS：Where's Sandra, Bob?","I want her.","BOB: Do you want to speak to her?","THE BOSS：Yes, I do.","I want her to come to","my office.","Tell her to come at once.","SANDRA: Did you want to see me?","THE BOSS：Ah, yes, Sandra.","How do you spell",`"intelligent'?`,"Can you tell me?","SANDRA: I-N-T-E-L-L-I-G-E-N-T.","THE BOSS：That's right.","You've typed it with only one","'L'. This letter's full of","mistakes. I want you to type","it again.","SANDRA: Yes, I'll do that.","I'm sorry about that.","THE BOSS：And here's a little present","for you.","SANDRA: What's it?","THE BOSS：It's a dictionary.","I hope it'll help you."],zh:["老 板：鲍勃，桑德拉在哪儿？我要找她。","鲍 勃：您要同她谈话吗？","老 板：是的，我要她到我的办公室来。","叫她马上就来。","桑德拉：您找我吗？",'老 板：啊，是的，桑德拉。"intelligent"',"怎样拼写？你能告诉我吗？","桑德拉：I-N-T-E-L-L-I-G-E-N-T。","老 板：对的。但你只打了1个“L”。","这封信里错误百出。我要你重打一遍。","桑德拉：是，我重打。对此我感到很抱歉。","老 板：这里有一件小礼物送你。","桑德拉：是什么？","老 板：是本词典。我希望它能对你有所帮助。"],words:[{en:"spell",cn:"v. 拼写"},{en:"intelligent",cn:"adj. 聪明的，有智慧的"},{en:"mistake",cn:"n. 错误"},{en:"present",cn:"n. 礼物"},{en:"dictionary",cn:"n. 词典"}]},{lesson:107,title:"It’s too small",titleCn:"",en:["Assistant: Do you like this dress, madam?","Lady: I like the colour very much. It’s a lovely dress, but it’s too small for me.","Assistant: What about this one? It’s a lovely dress. It’s very smart.","Short skirts are in fashion now. Would you like to try it?","Lady: All right.","Lady: I’m afraid this green dress is too small for me as well.","It’s smaller than the blue one.","Lady: I don’t like the colour either.","It doesn’t suit me at all. I think the blue dress is prettier.","Lady: Could you show me another blue dress?","I want a dress like that one, but it must be my size.","Assistant: I’m afraid I haven’t got a larger dress. This is the largest dress in the shop."],zh:["店员：夫人，您喜欢这件衣服吗？","女士：我很喜欢这颜色。这件漂亮的衣服，","可是对我来说太小了。","店员：这件怎么样？这是件漂亮的衣服，","它很时髦。短裙现在很流行。","您要试一试吗？","女士：好吧。","店员：恐怕这件绿色的我穿着也太小了。","它比那件蓝色的还要小。","女士：我也不喜欢这种颜色。这颜色我穿","根本不合适。我认为那件蓝色的更","漂亮些。","女士：您能再给我看一件蓝色的吗？","我想一件和那件一样的，","但必须是我的尺寸。","店员：恐怕没有更大的了。","这是店里最大一件。"],words:[{en:"madam",cn:"n. 夫人，女士（对妇女的尊称）"},{en:"smart",cn:"adj. 漂亮的"},{en:"as well",cn:"同样"},{en:"suit",cn:"v. 适于"},{en:"pretty",cn:"adj. 漂亮的"}]},{lesson:109,title:"A good idea",titleCn:"",en:["Betty: Shall I make some coffee, Jane?","Jane: That’s a good idea, Betty.","Betty: It’s ready. Do you want any milk?","Jane: Just a little please.","Betty: What about some sugar? Two teaspoonfuls?","Jane: No, less than that. One and a half teaspoonfuls please. That’s enough for me.","Jane: That was very nice.","Betty: Would you like some more?","Jane: Yes, please.","Jane: I’d like a cigarette, too. May I have one?","Betty: Of course. I think there are a few in that box.","Jane: I’m afraid it’s empty.","Betty: What a pity!（真遗憾）","Jane: It doesn’t matter.","Betty: Have a biscuit instead. Eat more and smoke less!","Jane: That’s very good advice!"],zh:["夏洛特：我来煮点咖啡好吗，简？","简：这是个好主意，夏洛特。","夏洛特：咖啡好了，你要放点奶吗？","简：请稍加一点。","夏洛特：加些糖怎么样？两茶匙行吗？","简：不，再少一些。请放一勺儿半。","那对我已足够了。","简：太好了。","夏洛特：你再来点吗？","简：好的，请再来一点。","简：我还想抽枝烟。可以给我一枝吗？","夏洛特：当然可以。我想那个盒子里有一些。","简：恐怕盒子是空的。","夏洛特：真遗憾！","简：没关系。","夏洛特：那就吃块饼干吧。多吃点，少抽点！","简：这是极好的忠告啊！"],words:[{en:"idea",cn:"n. 主意"},{en:"a little",cn:"少许（用于不可数名词之前）"},{en:"teaspoonful1",cn:"n. 一满茶匙"},{en:"less",cn:"adj. (little 的比较级)较少的，更小的"},{en:"a few",cn:"几个（用于可数名词之前）"},{en:"pity",cn:"n. 遗憾"},{en:"instead",cn:"adv. 代替"},{en:"advice",cn:"n. 建议，忠告"}]},{lesson:111,title:"The most expensive model",titleCn:"最昂贵的型号",en:["MR.FRITH：I like this television very much. How much does it cost?","ASSISTANT：It's the most expensive model in the shop. It costs five hundred pounds.","MRS. FRITH：That's too expensive for us. We can't afford all that money.","ASSISTANT：This model's less expensive than that one. It's only three hundred pounds. But, of course, it's not as good as the expensive one.","MR. FRITH: I don't like the model. The other model's more expensive, but it's worth the money.","MR. FRITH: Can we buy it on instalments?","ASSISTANT：Of course. You can pay a deposit of thirty pounds, and then fourteen pounds a month for three years.","MR. FRITH：Do you like it, dear?","MRS. FRITH：I certainly do, but I don't like the price. You always want the best, but we can't afford it. Sometimes you think you're a millionaire!","MR.FRITH：Millionaires don't buy things on instalments!"],zh:["弗里斯先生：我非常喜欢这台电视机。请问它多少钱？","店 员：这是店里最贵的型号。它的售价是500英镑。","弗里斯夫人：这对我们来说是太贵了。我们花不起那么多钱。","店 员：这种型号的比那种要便宜些。它只要300英镑。但是，它当然没有价钱高的那种好。","弗里斯先生：我不喜欢这种型号。那一种型号价格是贵一些，但它值这么多钱。","店 员：当然可以。您可以先付30英镑定金，然后每月14镑，3年付清。","弗里斯先生：你喜欢吗，亲爱的？","弗里斯夫人：我当然喜欢， 但是我不喜欢这个价钱。你总是要买最好的，可我们买不起。有时候你认为自己是个百万富翁！","弗里斯先生：百万富翁是不会分期付款买东西的！"],words:[{en:"model n.",cn:"模型"},{en:"afford v.",cn:"付得起（钱）"},{en:"deposit n.",cn:"预付定金"},{en:"instalment n.",cn:"分期付款"},{en:"price n.",cn:"价格"},{en:"millionaire n.",cn:"百万富翁"}]},{lesson:113,title:"small change",titleCn:"",en:["Conductor1: Fares please!","Man: Trafalgar Square please.","Conductor: I’m sorry, sir. I can’t change a pound note. Haven’t you got any small change?","Man: I’ve got no small change, I’m afraid.","Conductor: I’ll ask some of the passengers.","Conductor: Have you any small change, sir?","1st Passenger: I’m sorry. I’ve got none.","2ndPassenger: I haven’t got any either.","Conductor: Can you change this pound note, madam?","3rd Passenger: I’m afraid I can’t.","4th Passenger: Neither can I.","Conductor: I’m very sorry, sir. You must get off the bus.","None of our passengers can change this note. They’re all millionaires!","Two Tramps: Except us, conductor.","1st Tramp3: I’ve got some small change.","2nd Tramp: So have I."],zh:["售票员： 请买票！","男 子： 请买一张到特拉法加广场的票。","售票员： 对不起，我找不开10英镑的钞票。","您没有零钱吗？","男 子： 恐怕我没有零钱。","售票员： 我来问问其他乘客。","售票员： 先生，您有零钱吗？","乘 客1： 对不起，我没有。","乘 客2： 我也没有。","售票员： 夫人，您能把这10英镑的钞票","换开吗？","乘 客3： 恐怕不能。","乘 客4： 我也不能。","售票员： 非常抱歉，先生。您必须下车。","我们的乘客中没人能换开这张","钞票。","他们都是百万富翁！","二流浪汉：我们俩除外。","流浪汉1： 我有零钱。","流浪汉2： 我也有。"],words:[{en:"conductor",cn:"n. 售票员"},{en:"fare",cn:"n. 车费, 车票"},{en:"change",cn:"v. 兑换（钱）"},{en:"note",cn:"n. 纸币"},{en:"passenger",cn:"n. 乘客"},{en:"none",cn:"pron.没有任何东西"},{en:"neither",cn:"adv. 也不"},{en:"get off",cn:"下车"},{en:"tramp",cn:"n. 游浪汉"},{en:"except",cn:"prep.除……外"}]},{lesson:115,title:"Not ….",titleCn:"",en:["Helen: Isn’t there anyone at home?","Jim: I’ll knock again, Helen. Everything’s very quiet. I’m sure there’s no one at home.","Helen: But that’s impossible. Karol and Tom invited us to lunch. Look through the window.","Helen: Can you see anything?","Jim: Nothing at all.","Helen: Let’s try the back door.","Jim: Look! Everyone’s in the garden.","Pat: Hello, Helen. Hello, Jim.","Tom: Everybody wants to have lunch in the garden. It’s nice and warm out here.","Pat: Come and have something to drink.","Jim: Thanks, Karol . May I have a glass of beer please?","Pat: Beer? There’s none left. You can have some lemonade. (柠檬水)","Jim: Lemonade!","Tom: Don't believe her, Jim. She’s only joking. Have some beer!"],zh:["海 伦：家里没有人吗？","吉 姆：海伦，我再敲一次。毫无动静，肯定","家里没有人。","海 伦：但这是不可能的。卡罗尔和汤姆请","我们来吃午饭。从窗子往里看看。","海 伦：你能看见什么吗？","吉 姆：什么也看不见。","海 伦：让我们到后门去试试。","吉 姆：瞧！大家都在花园里。","卡罗尔：你好，海伦。你好，吉姆。","汤 姆：大家都想在花园里吃午饭。","这外面挺暖和。","卡罗尔：来喝点什么。","汤 姆：谢谢，卡罗尔。给我一杯啤酒好吗？","卡罗尔：啤酒？一点都不剩了。","你可以喝点柠檬水。","吉 姆：柠檬水！","汤 姆：吉姆，别信她的。她只是在开玩笑。","喝点啤酒吧！"],words:[{en:"anyone",cn:"pron.（用地疑问句，否定句）任何人"},{en:"knock",cn:"v. 敲，打"},{en:"everything",cn:"pron.一切事情"},{en:"quiet",cn:"adj. 宁静的，安静的"},{en:"impossible",cn:"adj. 不可能的"},{en:"invite",cn:"v. 邀请"},{en:"anything",cn:"pron.任何东西"},{en:"nothing",cn:"pron.什么也没有"},{en:"lemonade",cn:"n. 柠檬水"},{en:"joke",cn:"v. 开玩笑"}]},{lesson:117,title:"Tommy’s breakfast",titleCn:"",en:["When my husband was going into the dining-room this morning , he dropped some coins on the floor.","There were coins everywhere. We looked for them, but we could not find them all.","While we were having breakfast, our little boy, Tommy, found two small coins on the floor.","He put them both into his mouth. We both tried to get the coins, but it was too late. Tommy had already swallowed them!","Later that morning, when I was doing the housework, my husband telephoned me from the office.","“How’s Tommy?” he asked.","“I don’t know,” I answered, “Tommy’s been to the lavatory three times this morning, but I haven’t had any change yet!”"],zh:["今天早晨我丈夫走进饭厅时，把一些硬币掉在地上了。","到处都是硬币。我们虽然找了，但没有把它们全部找到。","正当我们吃早饭时，我们的小男孩汤米在地上找到两枚小硬币。","他把这两枚硬币全都放进嘴里。我们俩都试图把这两枚硬币拿出来，但太迟了。汤米已经把硬币咽了下去！","那天下午的晚些时候，当我正做家务时，我丈夫从办公室打来电话。","“汤米怎么样？”他问。“我不知道”，我回答说，“今天上午汤米去了3次厕所了，但我还没看到硬币！”"],words:[{en:"dinning2 room",cn:"饭厅"},{en:"coin",cn:"n. 硬币"},{en:"mouth",cn:"n. 嘴"},{en:"swallow",cn:"v. 吞下"},{en:"later",cn:"adv. 后来"},{en:"toilet",cn:"n. 厕所，盥洗室"}]},{lesson:119,title:"A true story",titleCn:"",en:["Do you like stories? I want to tell you a true story. It happened to a friend of mine a year ago.","While my friend, George, was reading in bed, two thieves climbed into his kitchen. After they had entered the house, they went into the dining-room. It was very dark, so they turned on a torch. Suddenly, they heard a voice behind them. “What’s up? What’s up?”(什么事) someone called. The thieves dropped the torch and ran away as quickly as they could.","George heard the noise and came downstairs quickly. He turned on the light, but he couldn’t see anyone. The thieves had already gone. But George’s parrot, Henry, was still there.","“What’s up, George?” he called.","“Nothing, Henry,” George said and smiled.","“Go back to sleep.”"],zh:["你喜欢听故事吗？我要告诉你一个真实的故事。这是一年前发生在我的一个朋友身上的故事。","当我的朋友乔治在床上看书时，两个小偷爬进了他的厨房。","他们进到屋里后，走进了饭厅。饭厅很暗，于是他们打开了手电筒。","突然他们听到身后有声音。“什么事？什么事？”有人叫着。小偷扔下了手电筒，飞快地逃走了。","乔治听到了响声，迅速地下了楼。","他开了灯，但不见一个人。小偷逃走了。","但时乔治的鹦鹉亨利仍在那里。“什么事，乔治？”它叫着。“没事，亨利。”乔治笑着说，“接着睡觉吧。”"],words:[{en:"story",cn:"n. 故事"},{en:"happen",cn:"v. 发生"},{en:"thief",cn:"n. 贼"},{en:"enter",cn:"v. 进入"},{en:"dark",cn:"adj. 黑暗的"},{en:"torch",cn:"n. 手电筒"},{en:"voice",cn:"n. （说话的）声音"},{en:"parrot",cn:"n. 鹦鹉"}]},{lesson:121,title:"The man in the hat",titleCn:"",en:["Customer: I bought two expensive dictionaries here half an hour ago, but I forgot to take them with me.","Manager: Who served you, sir?","Customer: The lady who is standing behind the counter.","Manager: Which books did you buy?","Customer: The books which are on the counter.","Manager: Did you serve this gentleman half an hour ago, Miss Roberts?","He says he’s the man who bought these books.","Miss Roberts: I can’t remember, sir. The man whom I served was wearing a hat.","Manager: Have you got a hat, sir?","Customer: Yes, I have.","Manager: Would you put it on, please?","Customer: All right.","Manager: Is this the man that you served, Miss Roberts?","Miss Roberts: Yes, sir. I recognize him now."],zh:["顾 客：半小时以前我在这里买了两本很","贵的辞典，但是我忘了拿走。","经 理：是谁接待您的，先生？","顾 客：站在柜台后面的那位女士。","经 理：您买的是两本什么书？","顾 客：就是柜台上的那两本。","经 理：卡罗琳，半小时前你接待过这位先生","吗？他说他就是买这两本书的人。","卡罗琳：我记不起来了。我接待的那个人戴着","一顶帽子。","经 理：先生，您有帽子吗？","顾 客：有的，我有帽子。","经 理：请您把帽子戴上好吗？","顾 客：好吧。","经 理：卡罗琳，","这就是你接待过的那个人吗？","卡罗琳：是他。我现在认出他来了。"],words:[{en:"customer",cn:"n. 顾客"},{en:"forget (forgot, forgotten)",cn:"v. 忘记"},{en:"manager",cn:"n. 经理"},{en:"serve",cn:"v. 照应，服务，接待"},{en:"counter",cn:"n. 柜台"},{en:"recognize",cn:"v. 认出"}]},{lesson:123,title:"A trip to Australia",titleCn:"",en:["Bill: Look, Scott. This is a photograph I took during my trip to Australia.","Bob: Let me see it, Bill.","Bob: This is a good photograph. Who are these people?","Bill: They’re people I met during the trip.","Bill: That’s the ship we traveled on.","Bob: What a beautiful ship!","Bob: Who’s this?","Bill: That’s the man I told you about. Remember?","Bob: Ah yes. The one who offered you a job in Australia.","Bill: That’s right.","Bob: Who’s this?","Bill: Guess!","Bob: It’s not you, is it?","Bill: That’s right.","Bill: I grew a beard during the trip, but I shaved it off when I came home.","Bob: Why did you shave it off?","Bill: My wife didn’t like it!"],zh:["迈 克：看，这是我到澳大利来旅行时","拍的一张照片。","斯科特：让我看看，迈克。","斯科特：这是一张很好的照片。这些人是谁。","迈 克：他们是我旅行时认识的人。","迈 克：这是我们所乘的那条船。","斯科特：多漂亮的船啊！","斯科特：这是谁？","迈 克：这就是我跟你说过的那个人。","还记得吗？","斯科特：啊，记得。就是在澳大利亚给你工作","的那个人。","迈 克：对。","斯科特：这是谁？","迈 克：你猜！","斯科特：这不是你，对吗？","迈 克：不，是我。","迈 克：我在旅行时留了胡子，","但我回到家时就把它刮了。","斯科特：你为什么把它刮了？","迈 克：我妻子不喜欢！"],words:[{en:"during",cn:"prep.在……期间"},{en:"trip",cn:"n. 旅行"},{en:"travel",cn:"v. 旅行"},{en:"offer",cn:"v. 提供"},{en:"job",cn:"n. 工作"},{en:"guess",cn:"v. 猜"},{en:"grow (grew, grown)",cn:"v. 长，让……生长"},{en:"beard",cn:"n. （下巴上的）胡子，络腮胡子"}]},{lesson:125,title:"Tea for two",titleCn:"",en:["Susan: Can’t you come in and have tea now, Peter?","Peter: Not yet, dear. I must water the garden first.","Susan: Do you have to water it now?","Peter: I’m afraid I must. Look at it! It’s terribly dry.","Susan: What a nuisance!（真讨厌）","Peter: Last summer it was very dry, too. Don’t you remember? I had to water it every day.","Susan: Well, I’ll have tea by myself.","Susan: That was quick! Have you finished already?","Peter: Yes, dear. Look out of the window.","Susan: Good heaven! It’s raining. That means you needn’t water the garden.","Peter: That was a pleasant surprise. It means I can have tea, instead."],zh:["苏珊：彼得，你现在能进来喝茶吗？","彼得：还不能。我得先给花园浇水。","苏珊：你一定得现在浇吗？","彼得：恐怕我得现在浇。你看看，干得厉害。","苏珊：真讨厌！","彼得：去年夏天也是干得很。","你记得了吗？我不得不每天浇水。","苏珊：好吧，我一个喝茶了。","苏珊：好快啊！你已经浇完了？","彼得：是的。你看看窗外。","苏珊：下雨了，这就是就是说，","你不必给花园浇水了。","彼得：这是意想不能的好事。","这意味着我反倒可以喝茶了。"],words:[{en:"water",cn:"v. 浇水"},{en:"terribly",cn:"adv. 非常"},{en:"dry",cn:"adj. 干燥的，干的"},{en:"nuisance",cn:"n. 讨厌的东西或人"},{en:"mean (meant, meant)",cn:"v. 意味着，意思是"},{en:"surprise",cn:"n. 惊奇，意外的事"}]},{lesson:127,title:"A famous actress",titleCn:"",en:["Kate: Can you recognize that woman, Millie?","Millie: I think I can, Kate. It must be Karen Marsh, the actress.","Kate: I thought so. Who’s that beside her?","Millie: That must be Conrad Reeves.","Kate: Conrad Reeves, the actor? It can’t be. Let me have another look.","I think you’re right! Isn’t he her third husband?","Millie: No, He must be her fourth or fifth.","Kate: Doesn’t Karen Marsh look old!","Millie: She does, doesn’t she! I read she’s twenty-nine, but she must be at least forty.","Kate: I’m sure she is.","Millie: She was a famous actress when I was still a schoolgirl.","Kate: That was a long time ago, wasn’t it?","Millie: Not that long ago! I’m not more than twenty-nine myself."],zh:["凯特：莉兹，你能认出那个女人吗？","莉兹：我想我认得出来，凯特。那一定是女","演员卡.马会。","凯特：我也这样想。她旁边的那个人是谁？","莉兹：一定是康拉德.里弗斯。","凯特：康拉德.里弗斯，那个男演员吗？","不可能是。让我再看一看。","我想你是对的。他不是她的第3个","丈夫吗？","莉兹：不，他一定是她的第4个或第5个丈夫。","凯特：卡伦看上去不显老嘛！","莉兹：是的，谁说不是呢！我从报上看到她","是29岁，但她一定至少有40岁了。","凯特：我肯定她有40岁了。","莉兹：当我还是学生时，她就是个著名的","演员了。","凯特：那是好久以前的事了。是吗？","莉兹：不，没有那么久。我自己现在还没","29岁呢。"],words:[{en:"famous",cn:"adj. 著名的"},{en:"actress",cn:"n. 女演员"},{en:"at least",cn:"至少"},{en:"actor",cn:"n. 男演员"},{en:"read (read, read)",cn:"v. 通过阅读得知"}]},{lesson:129,title:"70 miles an hour",titleCn:"",en:["Ann: Look, Harry! That policeman’s waving to you. He wants you to stop.","Policeman: Where do you think you are? On a race track?","You must have been driving at seventy miles an hour.","Harry: I can’t have been.","Policeman: I was doing eighty when I overtook you.","Policeman: Didn’t you see the speed limit?","Harry: I’m afraid I didn’t, officer. I must have been dreaming .","Ann: He wasn’t dreaming, officer. I was telling him to drive slowly.","Harry: That’s why I didn’t see the sign.","Policeman: Let me see your driving-license and your insurance certificate.","Policeman: I won’t charge you this time. But you’d better not do it again!","Harry: Thank you. I’ll certainly be more careful.","Ann: I told you to drive slowly, Harry.","Harry: You always tell me to drive slowly, darling.","Ann: Well, next time you’d better take my advice!"],zh:["安：瞧，加里！那个警察正朝你挥手呢。","他要你停下来。","警察：你认为你现在是在哪儿？","在赛车道上吗？你刚才一定是以每小时","70英里的速度开车。","加里：我不会开得那么快的。","警察：我是以每小时80英里的速度赶上你的。","警察：难道你没看见限速牌吗？","加里：恐怕我没有看见，警官。","我一定思想开小差了。","安：警官，他思想没有开小差。","我刚才正告诉他开慢点。","安里：所以我才没看见那牌子。","警察：让我看一看你的驾驶执照。","警察：这次我就不罚你款了。但你最好不要再","开得这样快。","加里：谢谢您。我以后一定会多加注意。","安：加里，我刚才叫你开慢点吧。","加里：你总是叫我开慢点，亲爱的。","安：好啦，下次你最好还是听从我的劝告！"],words:[{en:"wave",cn:"v. 招手"},{en:"track",cn:"n. 跑道"},{en:"mile",cn:"n. 英里"},{en:"overtake5 (overtook, overtaken)",cn:"v. 从后面超越，超车"},{en:"speed limit",cn:"限速"},{en:"dream",cn:"v. 做梦，思想不集中"},{en:"sign",cn:"n. 标记，牌子"},{en:"driving licence6",cn:"驾驶执照"},{en:"charge",cn:"v. 罚款"},{en:"darling",cn:"n. 亲爱的（用作表示称呼）"}]},{lesson:131,title:"Don’t be so sure",titleCn:"",en:["Roy: Where are you going to spend your holidays this year, Harry?","Harry: We may go abroad. I’m not sure. My wife wants to go to Egypt.","I’d like to go there, too. We can’t make up our minds.","Roy: Will you travel by sea or by air?","Harry: We may travel by sea.","Roy: It’s cheaper, isn’t it?","Harry: It may be cheaper, but it takes a long time.","Roy: I’m sure you will enjoy yourselves.","Harry: Don’t be so sure. We may not go anywhere. My wife always worries too much.","Who’s going to look after the dog?","Who’s going to look after the house?","Who’s going to look after the garden?","We have this problem every year.","In the end, we stay at home and look after everything!"],zh:["马丁：加里，今年你们打算去哪里度假？","加里：我们可能到国外去，但我不敢肯定。","我妻子想到埃及去，我也想去那儿。","我们还拿不定主意。","马丁：你们乘船去，还是乘飞机去？","加里：我们可能乘船去。","马丁：这更便宜些，是吗？","加里：可能是便宜些，但花的时间长。","马丁：我肯定你们一定会玩得很痛快。","加里：别那么肯定。我们可能哪里也去不成。","我妻子总是担心那的。谁来照看狗啦，","谁来看管房子啦，谁来照料花园啦，","我们每年都碰到这类问题。算了，","我们呆在家里来照看一切。"],words:[{en:"Egypt",cn:"n. 埃及"},{en:"abroad",cn:"adv. 国外"},{en:"worry",cn:"v. 担忧"}]},{lesson:133,title:"Sensational news",titleCn:"",en:["Reporter: Have you just made a new film, Miss Marsh?","Miss Marsh: Yes, I have.","Reporter: Are you going to make another?","Miss Marsh: No, I’m not. I’m going to retire. I feel very tired.","I don't want to make another film for a long time.","Kate: let’s buy a newspaper, Millie.","Listen to this!","“ Karen Marsh: Sensational News!（轰动新闻） By our reporter, Alan Jones. Miss Karen Marsh arrived at London Airport today. She was wearing a blue dress and a mink coat. She told me she had just made a new film. She said she was not going to make another. She said she was going to retire. She told reporters she felt very tired and didn’t want to make another film for a long time.”","Millie: Well, fancy that, Kate!"],zh:["记 者：您刚拍完一部新电影吗，","马什小姐？","马什小姐：是的，我刚拍完。","记 者：您准备再拍一部吗？","马什小姐：不，我不准备拍了。","我准备退休了。我感觉累得很。","我早就不想再拍片子了。","凯 特：我们买份报纸吧。莉兹。","你听这段：“卡伦.马什：","爆炸性新闻！由本报记者艾伦.","琼斯报导。卡伦.马什今天到达","伦敦机场。她穿着一身蓝色的","套装和一件貂皮大衣。她告诉","我她刚拍完一部新片子。她不","准备再拍电影了。她说她准备","退休。她告诉记者她感到很疲","劳，早就不想再拍电影了。","莉 兹：我很想知道为什么"],words:[{en:"reporter",cn:"n. 记者"},{en:"sensational",cn:"adj. 爆炸性的，耸人听闻的"},{en:"mink coat",cn:"貂皮大衣"}]},{lesson:135,title:"The latest report",titleCn:"",en:["Reporter: Are you really going to retire, Miss marsh?","Miss Marsh: I may. I can’t make up my mind. I shall have to ask my future husband. He won’t let me make another film.","Reporter: Your future husband, Miss Marsh?","Miss Marsh: Yes. Let me introduce him to you. His name is Carlos.","We are going to get married next week.","Kate: Look, Millie! Here’s another report about Karen Marsh. Listen:","“ Karen Marsh: The Latest. At her London Hotel today Miss Marsh told reporters she might retire. She said she couldn’t make up her mind. She said she would have to ask her future husband. She said her future husband would not let her make another film. Then she introduced us to Carlos and told us they would get married next week.”","Millie: That’s sensational news, isn’t it, Kate?","Kate: It certainly is. He’ll be her sixth husband!"],zh:["记 者：马什小姐，您真的准备退休吗？","马什小姐：有可能退。我还拿不定主意。","我得问一下我的未婚夫。他不会","再让我拍电影了。","记 者：您的未婚夫，马什小姐？","马什小姐：是的，让我把他给你们介绍一下。","他叫卡洛斯。下星期我们就要","结婚了。","凯 特：看啊，莉兹！这又有一篇关于卡","伦.马会的报道。你听，“卡伦.","马什：最新消息。今天在伦敦旅","馆，马什小姐告诉记者她可能要","退休。她说她还拿不定主意。她","说她得问问她的未婚夫。她说她","的未婚夫不会再让她拍电影。","然后她把我们介绍给卡洛斯，","并告诉我们说他们下星期结婚。”","莉 兹：凯特，这真是条轰动的消息，","是不是？","凯 特：当然啦。他将是她的第6个丈夫！"],words:[{en:"future",cn:"n. 未来的"},{en:"get married",cn:"结婚"},{en:"hotel",cn:"n. 饭店"},{en:"latest",cn:"adj. 最新的"},{en:"introduce",cn:"v. 介绍"}]},{lesson:137,title:"A pleasant dream",titleCn:"",en:["June: Are you doing the football pools(赌注), Brian?","Brian: Yes, I’ve nearly finished, June. I’m sure we will win something this week.","June: You always say that, but we never win anything! What will you do if you win a lot of money?","Brian: If I win a lot of money , I shall buy you a mink coat.","June: I don’t want a mink coat! I want to see the world.（见世面）","Brian: All right. If we win a lot of money, we shall travel around the world and we shall stay at the best hotels. Then we shall return home and buy a big house in the country. We shall have a beautiful garden and…","June: But if we spend all that money we shall be poor again. What shall we do then?","Brian: If we spend all the money, we shall try and win the football pools again.","June: It’s a pleasant dream, but everything depends on “if”!"],zh:["朱 莉：布赖恩，你正在下足球赛的赌注吗？","布赖恩：是的。我这就做完了。朱莉。","我敢肯定这星期我们会赢一点的。","朱 莉：你老是那样说，但是我们从来没","赢过！要是你赢了许多钱，你打算","做什么呢？","布赖恩：要是我赢了许多钱，我给你买件","貂皮大衣。","朱 莉：我不要貂皮大衣。我要去见风世面。","布赖恩：好吧。要是我们赢了很多钱，我们","就去周游世界，并且住最好的旅馆。","然后我们返回家园，在乡下买幢大","房子。我们将有一个漂亮的花园和","朱 莉：但是如果我们把所有钱都花光了，","我们又会变穷的。那时我们怎么","办呢？","布赖恩：如果我们花光了所有钱，我们设法","在足球赛赌注上再赢一次。","朱 莉：这是个美好的梦，但一切都取决于","“如果”！"],words:[{en:"football",cn:"n. 足球"},{en:"pool",cn:"n. 赌注"},{en:"win (won, won)",cn:"v. 赢"},{en:"world",cn:"n. 世界"},{en:"poor",cn:"adj. 贫穷的"},{en:"depend",cn:"v. 依靠（on）"}]},{lesson:139,title:"Is that you, John?",titleCn:"",en:["Mr Grimes: Is that you, John?","John Smith: Yes, speaking.","Mr Grimes: Tell Mary we shall be late for dinner this evening.","John Smith: I’m afraid I don’t understand.","Mr Grimes: Hasn’t Mary told you? She invited betty and me to dinner this evening. I said I would be at your house at six o’clock, but the boss wants me to do some extra work. I’ll have to stay at the office. I don’t know when I shall finish. Oh, and by the way, my wife wants to know if Mary needs any help.","John Smith: I don’t know what you’re talking about.","Mr Grimes: That is John Smith, isn’t it?","John Smith: Yes, I’m John Smith.","Mr Grimes: You are John Smith, the engineer, aren’t you?","John Smith: That’s right.","Mr Grimes: You work for the Overseas Engineering Company, don’t you?","John Smith: No, I don’t. I’m John Smith the telephone engineer and I’m repairing your telephone line."],zh:["格雷厄姆.特纳：是你吗，约翰？","约 翰.史 密斯：是我，请讲。","格雷厄姆.特纳：你告诉玛丽，今晚吃饭将晚到一会儿。","约 翰.史 密斯：恐怕我还不明白您的意思。","格雷厄姆.特纳：玛丽没有告诉你吗？","她邀请我和夏洛特今晚去","吃饭。我说过我6点到你家，","但老板要我加班。我不得","不留在办公室，不知道什","么时候才能结束。喔，","顺便问一问，我妻子想知","道玛丽是否需要帮忙。","约 翰.史 密斯：我不知道您在说些什么。","格雷厄姆.特纳：你是约翰.史密斯，对吗？","约 翰.史密 斯： 是的，我是约翰.史密斯。","格雷厄姆.特纳：你是工程师约翰.史密斯，","对吗？","约 翰.史 密斯：对。","格雷厄姆.特纳：你在海外工程公司上班，","是吗？","约 翰.史 密斯：不，不是。我是电话工程","师约翰.史密斯，我正在","修理您的电话线。"],words:[{en:"extra",cn:"adj. 额外的"},{en:"overseas",cn:"adj. 海外的，国外的"},{en:"engineering",cn:"n. 工程"},{en:"company",cn:"n. 公司"},{en:"line",cn:"n. 线路"}]},{lesson:141,title:"Sally’s first train ride",titleCn:"",en:["Last week, my four year old daughter, Sally, was invited to a children’s party. I decided to take her by train. Sally was very excited because she had never travelled on a train before. She sat near the window and asked questions about everything she saw. Suddenly, a middle-aged lady got on the train and sat opposite Sally.","“Hello, little girl.” She said. Sally did not answer, but looked at her curiously.","The lady was dressed in a blue coat and a large, funny hat. After the train had left the station, the lady opened her handbag and took out her powder compact4(粉盒). She then began to make up her face.","“Why are you doing that?” Sally asked.","“To make myself beautiful,” the lady answered. She put away her compact and smiled kindly.","“But you are still ugly.” Sally said. Sally was amused, but I was very embarrassed!"],zh:["上周，我4岁的女儿萨莉被邀请去参加一个儿童聚会。我决定带她乘火车去。萨莉非常激动，因为她从未乘过火车。她靠车窗坐着，对她所看到的一切都要问个明白。突然，一个中年妇女上了火车，坐在萨莉的对面。“你好，小姑娘，”她说。萨莉没回答，却好奇地看着她。那位妇女穿着一件蓝色的大衣，戴着一顶大而滑稽的帽子。火车开出车站后，那位妇女打开了手提包，拿出了粉盒。然后她开始打扮起来。“你为什么要那样做呢？”萨莉问。“为了把自己打扮漂亮啊，”那位妇女答道。她放好了粉盒，慈祥地微笑着。“可是你仍然难看呀，”萨莉说。萨莉感到很有趣，而我却很尴尬。"],words:[{en:"excited",cn:"adj. 兴奋的"},{en:"get on",cn:"登上"},{en:"middle-aged",cn:"adj. 中年的"},{en:"opposite",cn:"prep.在……对面"},{en:"curiously",cn:"adv.好奇地"},{en:"funny",cn:"adj. 可笑的，滑稽的"},{en:"powder",cn:"n. 香粉"},{en:"compact",cn:"n. 带镜的化妆盒"},{en:"kindly",cn:"adv. 和蔼地"},{en:"ugly",cn:"adj. 丑陋的"},{en:"amused",cn:"adj. 有趣的"},{en:"smile",cn:"v. 微笑"},{en:"embarrassed",cn:"adj. 尴尬"}]},{lesson:143,title:"A walk through the woods",titleCn:"林中散步",en:["I live in a very old town which is surrounded by beautiful woods. It is a famous beauty spot. On Sundays, hundreds of people come from the city to see our town and to walk through the woods. Visitors have been asked to keep the woods clean and tidy. Litter baskets have been placed under the trees, but people still throw their rubbish everywhere. Last Wednesday, I went for a walk in the woods. What I saw made me very sad. I counted seven old cars and three old refrigerators. The little baskets were empty and the ground was covered with pieces of paper, cigarette ends, old tyres, empty bottles and rusty tins. Among the rubbish, I found a sign which said, 'Anyone who leaves litter in these woods will be prosecuted!'"],zh:['我住在一个由美丽的树林环绕的古老的小镇上。这是一个著名的风景胜地。每逢星期天，有许许多人从城里来观赏我们的小镇，并在树林中散步。游客已被告知要保持树林的整洁。树下都已设置了废物筐，但是人们仍到处扔垃圾。上星期三我到树林里去散步。我所见到的一切使我非常难过。我数了一下，有7辆旧汽车和3个旧冰箱。废物筐是空的，而满地都是纸片、烟头、旧轮胎，空瓶子和生锈的空罐头盒。在垃圾堆中我发现了一块牌子，上面写着：“凡在此树林里丢弃垃圾者，将依法处置"。'],words:[{en:"surround",cn:"v.   包围"},{en:"wood",cn:"n.   树林"},{en:"beauty spot",cn:"风景点"},{en:"hundred",cn:"n.   百"},{en:"city",cn:"n.   城市"},{en:"through",cn:"prep.穿过"},{en:"visitor",cn:"n.   参观者，游客，来访者"},{en:"tidy",cn:"adj. 整齐的"},{en:"litter",cn:"n.   杂乱的东西"},{en:"litter basket",cn:"废物筐"},{en:"place",cn:"v.   放"},{en:"throw( threw; thrown)",cn:"v.   扔，抛"},{en:"rubbish",cn:"n.   垃圾"},{en:"count",cn:"v.   数，点"},{en:"cover",cn:"v.   覆盖"},{en:"piece",cn:"n.   碎片"},{en:"tyre1",cn:"n.   轮胎"},{en:"rusty",cn:"adj. 生锈的"},{en:"among",cn:"prep.在……之间"},{en:"prosecute4",cn:"v.   依法处置"}]}],m=["aria-label"],g=["id"],w=["stop-color"],p=["stop-color"],v=["fill"],I={x:"100",y:"122","text-anchor":"middle","font-family":"Helvetica, Arial, sans-serif","font-size":"76","font-weight":"700",fill:"#ffffff"},f=l({__name:"LessonCover",props:{lesson:{}},setup(o){const a=o,s=t(()=>a.lesson*137.508%360),i=t(()=>`hsl(${s.value}, 52%, 46%)`),h=t(()=>`hsl(${(s.value+42)%360}, 58%, 32%)`),r=t(()=>`lesson-cover-grad-${a.lesson}`);return(b,n)=>(y(),c("svg",{class:"lesson_cover",viewBox:"0 0 200 200",xmlns:"http://www.w3.org/2000/svg",role:"img","aria-label":"Lesson "+o.lesson+" cover"},[e("defs",null,[e("linearGradient",{id:r.value,x1:"0%",y1:"0%",x2:"100%",y2:"100%"},[e("stop",{offset:"0%","stop-color":i.value},null,8,w),e("stop",{offset:"100%","stop-color":h.value},null,8,p)],8,g)]),e("rect",{x:"0",y:"0",width:"200",height:"200",rx:"18",fill:`url(#${r.value})`},null,8,v),n[0]||(n[0]=e("circle",{cx:"168",cy:"34",r:"52",fill:"rgba(255,255,255,0.10)"},null,-1)),n[1]||(n[1]=e("circle",{cx:"18",cy:"186",r:"64",fill:"rgba(0,0,0,0.08)"},null,-1)),e("text",I,d(o.lesson),1),n[2]||(n[2]=e("text",{x:"100",y:"156","text-anchor":"middle","font-family":"Helvetica, Arial, sans-serif","font-size":"15","letter-spacing":"3",fill:"rgba(255,255,255,0.92)"},"LESSON",-1))],8,m))}}),S=u(f,[["__scopeId","data-v-10a30192"]]);export{S as L,k as l};
